insert into kb.procedure_versions(id, procedure_id, revision, status, locale, title, summary, required_step_count, content_hash) values ('7d43b69f-b2df-5730-9488-14c9e28f92dc'::uuid, '9b326e0d-f9f6-5ae3-a983-22d1e565e404'::uuid, 1, 'draft', 'ko-KR', '책상 상판과 전자기기 주변 청소', '전원을 먼저 정리하고 마른 먼지부터 걷은 뒤, 상판을 작은 면씩 닦아 완전히 말려요.', 5, 'ee868111e9da6782aa50665479bc21d22a419c5de5240f831d64557f684ebf78');
insert into kb.procedure_steps(id, procedure_version_id, step_no, stage_code, instruction, detail, completion_cue, caution, speech_text) values ('d81afa28-ab7b-59a4-882e-0f246ee3d6b2'::uuid, '7d43b69f-b2df-5730-9488-14c9e28f92dc'::uuid, 1, 'prepare', '도구와 작업 범위를 준비해요.', '마른 부드러운 천, 물기를 꼭 짤 수 있는 천과 작은 바구니를 옆에 두고 책상 한 구역만 정해요.', '닦을 한 구역과 도구가 준비됐어요.', '한 번에 책상 전체를 비우지 않아도 괜찮아요.', '도구와 작업 범위를 준비해요. 마른 부드러운 천, 물기를 꼭 짤 수 있는 천과 작은 바구니를 옆에 두고 책상 한 구역만 정해요.');
insert into kb.step_source_links(procedure_version_id, step_no, source_version_id, section_locator, support_note) values ('7d43b69f-b2df-5730-9488-14c9e28f92dc'::uuid, 1, '789fb545-60ce-51e2-b513-d0a782645106'::uuid, 'verified-scope:aci_home_routine', '검수자가 단계 문안과 출처의 적용 범위를 대조함');
insert into kb.procedure_steps(id, procedure_version_id, step_no, stage_code, instruction, detail, completion_cue, caution, speech_text) values ('3b82fef2-62b1-5c88-b988-3ec17a2e23df'::uuid, '7d43b69f-b2df-5730-9488-14c9e28f92dc'::uuid, 2, 'protect', '전자기기 전원을 끄고 선을 치워요.', '노트북·모니터·충전기의 전원을 끄고 가능한 선을 분리해 액체가 닿지 않는 곳으로 옮겨요.', '전원이 꺼지고 닦을 면에서 선이 떨어져 있어요.', '전자기기 틈으로 물이 흐르지 않게 해요.', '전자기기 전원을 끄고 선을 치워요. 노트북·모니터·충전기의 전원을 끄고 가능한 선을 분리해 액체가 닿지 않는 곳으로 옮겨요.');
insert into kb.step_source_links(procedure_version_id, step_no, source_version_id, section_locator, support_note) values ('7d43b69f-b2df-5730-9488-14c9e28f92dc'::uuid, 2, 'fe74460b-c981-53e9-9c4b-0f06aa60b56a'::uuid, 'verified-scope:cdc_home_cleaning', '검수자가 단계 문안과 출처의 적용 범위를 대조함');
insert into kb.step_source_links(procedure_version_id, step_no, source_version_id, section_locator, support_note) values ('7d43b69f-b2df-5730-9488-14c9e28f92dc'::uuid, 2, '213afb63-6240-58be-9627-a9d2db71ad8a'::uuid, 'verified-scope:aci_hard_surfaces', '검수자가 단계 문안과 출처의 적용 범위를 대조함');
insert into kb.procedure_steps(id, procedure_version_id, step_no, stage_code, instruction, detail, completion_cue, caution, speech_text) values ('f40d6db5-4390-5aa7-b42d-b9d507086f2a'::uuid, '7d43b69f-b2df-5730-9488-14c9e28f92dc'::uuid, 3, 'preclean', '큰 물건과 마른 먼지를 먼저 걷어요.', '남길 물건을 바구니에 잠시 옮기고 마른 천으로 부스러기와 먼지를 한쪽으로 모아 버려요.', '상판에 큰 물건과 느슨한 먼지가 남지 않았어요.', null, '큰 물건과 마른 먼지를 먼저 걷어요. 남길 물건을 바구니에 잠시 옮기고 마른 천으로 부스러기와 먼지를 한쪽으로 모아 버려요.');
insert into kb.step_source_links(procedure_version_id, step_no, source_version_id, section_locator, support_note) values ('7d43b69f-b2df-5730-9488-14c9e28f92dc'::uuid, 3, '789fb545-60ce-51e2-b513-d0a782645106'::uuid, 'verified-scope:aci_home_routine', '검수자가 단계 문안과 출처의 적용 범위를 대조함');
insert into kb.step_source_links(procedure_version_id, step_no, source_version_id, section_locator, support_note) values ('7d43b69f-b2df-5730-9488-14c9e28f92dc'::uuid, 3, 'd153c12d-48a4-5322-aa9e-fae37414889b'::uuid, 'verified-scope:me_indoor_air', '검수자가 단계 문안과 출처의 적용 범위를 대조함');
insert into kb.procedure_steps(id, procedure_version_id, step_no, stage_code, instruction, detail, completion_cue, caution, speech_text) values ('9662951a-1ef2-5017-af12-02d2a94c8bc6'::uuid, '7d43b69f-b2df-5730-9488-14c9e28f92dc'::uuid, 4, 'act', '물기를 꼭 짠 천으로 작은 면씩 닦아요.', '눈에 잘 띄지 않는 작은 곳부터 한 방향으로 닦고, 얼룩이 번지면 깨끗한 천 면으로 바꿔요.', '선택한 구역의 보이는 먼지와 자국이 닦였어요.', '색이 달라지거나 표면이 벗겨지면 멈춰요.', '물기를 꼭 짠 천으로 작은 면씩 닦아요. 눈에 잘 띄지 않는 작은 곳부터 한 방향으로 닦고, 얼룩이 번지면 깨끗한 천 면으로 바꿔요.');
insert into kb.step_source_links(procedure_version_id, step_no, source_version_id, section_locator, support_note) values ('7d43b69f-b2df-5730-9488-14c9e28f92dc'::uuid, 4, 'fe74460b-c981-53e9-9c4b-0f06aa60b56a'::uuid, 'verified-scope:cdc_home_cleaning', '검수자가 단계 문안과 출처의 적용 범위를 대조함');
insert into kb.step_source_links(procedure_version_id, step_no, source_version_id, section_locator, support_note) values ('7d43b69f-b2df-5730-9488-14c9e28f92dc'::uuid, 4, '213afb63-6240-58be-9627-a9d2db71ad8a'::uuid, 'verified-scope:aci_hard_surfaces', '검수자가 단계 문안과 출처의 적용 범위를 대조함');
insert into kb.procedure_steps(id, procedure_version_id, step_no, stage_code, instruction, detail, completion_cue, caution, speech_text) values ('831b7ff3-3c66-53e9-8864-7a3a60dd5db8'::uuid, '7d43b69f-b2df-5730-9488-14c9e28f92dc'::uuid, 5, 'dry', '마른 천으로 물기를 없애고 기기를 돌려놓아요.', '상판과 가장자리를 마른 천으로 닦고 완전히 마른 것을 확인한 뒤 전자기기와 선을 제자리에 둬요.', '상판이 마르고 전자기기 주변에 물기가 없어요.', null, '마른 천으로 물기를 없애고 기기를 돌려놓아요. 상판과 가장자리를 마른 천으로 닦고 완전히 마른 것을 확인한 뒤 전자기기와 선을 제자리에 둬요.');
insert into kb.step_source_links(procedure_version_id, step_no, source_version_id, section_locator, support_note) values ('7d43b69f-b2df-5730-9488-14c9e28f92dc'::uuid, 5, '213afb63-6240-58be-9627-a9d2db71ad8a'::uuid, 'verified-scope:aci_hard_surfaces', '검수자가 단계 문안과 출처의 적용 범위를 대조함');
insert into kb.review_events(id, entity_type, entity_version_id, decision, reason, reviewer_ref, created_at) values ('464f8207-8f68-5555-a3f2-0308028b757f'::uuid, 'procedure_version', '7d43b69f-b2df-5730-9488-14c9e28f92dc'::uuid, 'approved', '단계 순서·출처 범위·안전 문구·실행 가능성 검수 완료', 'knowledge-editor-2026-08-25', '2026-08-25T06:00:00Z'::timestamptz);
insert into kb.procedures(id, procedure_key) values ('9075fa17-a63e-5053-9633-210b843f2ed1'::uuid, 'sink-strainer-clean-v1');
insert into kb.procedure_versions(id, procedure_id, revision, status, locale, title, summary, required_step_count, content_hash) values ('8a39669d-51cb-584f-bb83-fa042f4af717'::uuid, '9075fa17-a63e-5053-9633-210b843f2ed1'::uuid, 1, 'draft', 'ko-KR', '싱크대 거름망과 싱크볼 청소', '거름망의 찌꺼기를 먼저 비우고 망 안팎을 부드럽게 닦아 헹군 뒤 완전히 말려요.', 6, '35429c59ebb668ba808da8f6dfebb5cdf4c266174c6230a87275ecdd172fa993');
insert into kb.procedure_steps(id, procedure_version_id, step_no, stage_code, instruction, detail, completion_cue, caution, speech_text) values ('6c1174c5-f230-5645-a8be-b49e48928815'::uuid, '8a39669d-51cb-584f-bb83-fa042f4af717'::uuid, 1, 'prepare', '장갑과 봉투, 부드러운 작은 솔을 준비해요.', '싱크대 사용을 잠시 멈추고 장갑, 음식물 봉투, 부드러운 솔, 깨끗한 물과 마른 천을 가까이 둬요.', '싱크대 물이 멈추고 준비물이 손에 닿아요.', '배수구 역류나 누수가 보이면 작업을 멈춰요.', '장갑과 봉투, 부드러운 작은 솔을 준비해요. 싱크대 사용을 잠시 멈추고 장갑, 음식물 봉투, 부드러운 솔, 깨끗한 물과 마른 천을 가까이 둬요.');
insert into kb.step_source_links(procedure_version_id, step_no, source_version_id, section_locator, support_note) values ('8a39669d-51cb-584f-bb83-fa042f4af717'::uuid, 1, 'fe74460b-c981-53e9-9c4b-0f06aa60b56a'::uuid, 'verified-scope:cdc_home_cleaning', '검수자가 단계 문안과 출처의 적용 범위를 대조함');
insert into kb.step_source_links(procedure_version_id, step_no, source_version_id, section_locator, support_note) values ('8a39669d-51cb-584f-bb83-fa042f4af717'::uuid, 1, 'f0f1a866-d5d2-50b8-92a8-257db1074c8f'::uuid, 'verified-scope:epa_mold_home', '검수자가 단계 문안과 출처의 적용 범위를 대조함');
insert into kb.procedure_steps(id, procedure_version_id, step_no, stage_code, instruction, detail, completion_cue, caution, speech_text) values ('d9ffdb6d-a1fd-5039-8c08-59e3d7f69181'::uuid, '8a39669d-51cb-584f-bb83-fa042f4af717'::uuid, 2, 'preclean', '싱크볼의 그릇과 큰 찌꺼기를 먼저 치워요.', '식기는 다른 곳에 두고 손으로 집을 수 있는 큰 찌꺼기는 봉투에 버려 배수구로 밀어 넣지 않아요.', '싱크볼과 거름망 주변에 큰 찌꺼기가 없어요.', '날카로운 조각이 의심되면 손으로 만지지 않아요.', '싱크볼의 그릇과 큰 찌꺼기를 먼저 치워요. 식기는 다른 곳에 두고 손으로 집을 수 있는 큰 찌꺼기는 봉투에 버려 배수구로 밀어 넣지 않아요.');
insert into kb.step_source_links(procedure_version_id, step_no, source_version_id, section_locator, support_note) values ('8a39669d-51cb-584f-bb83-fa042f4af717'::uuid, 2, 'fe74460b-c981-53e9-9c4b-0f06aa60b56a'::uuid, 'verified-scope:cdc_home_cleaning', '검수자가 단계 문안과 출처의 적용 범위를 대조함');
insert into kb.procedure_steps(id, procedure_version_id, step_no, stage_code, instruction, detail, completion_cue, caution, speech_text) values ('8f999dd6-849d-50d5-9bd0-727b462c71a4'::uuid, '8a39669d-51cb-584f-bb83-fa042f4af717'::uuid, 3, 'act', '거름망을 들어 찌꺼기를 비워요.', '거름망을 천천히 들어 봉투 위에서 뒤집고, 망 구멍에 남은 찌꺼기는 부드러운 솔로 바깥쪽부터 떼어내요.', '망 구멍을 막던 눈에 보이는 찌꺼기가 없어졌어요.', '억지로 분해해야 하는 부품은 건드리지 않아요.', '거름망을 들어 찌꺼기를 비워요. 거름망을 천천히 들어 봉투 위에서 뒤집고, 망 구멍에 남은 찌꺼기는 부드러운 솔로 바깥쪽부터 떼어내요.');
insert into kb.step_source_links(procedure_version_id, step_no, source_version_id, section_locator, support_note) values ('8a39669d-51cb-584f-bb83-fa042f4af717'::uuid, 3, 'fe74460b-c981-53e9-9c4b-0f06aa60b56a'::uuid, 'verified-scope:cdc_home_cleaning', '검수자가 단계 문안과 출처의 적용 범위를 대조함');
insert into kb.procedure_steps(id, procedure_version_id, step_no, stage_code, instruction, detail, completion_cue, caution, speech_text) values ('e39c608a-25d2-50a1-b697-e73192fcf40b'::uuid, '8a39669d-51cb-584f-bb83-fa042f4af717'::uuid, 4, 'act', '거름망 안팎과 테두리를 미지근한 물로 닦아요.', '미지근한 물에 적신 부드러운 솔로 안쪽·바깥쪽·테두리를 나눠 짧게 문지르고, 싱크볼의 보이는 자국도 부드러운 천으로 닦아요.', '거름망 안팎과 테두리에 느슨한 잔여물이 없어요.', '금속 수세미나 날카로운 도구는 쓰지 않아요.', '거름망 안팎과 테두리를 미지근한 물로 닦아요. 미지근한 물에 적신 부드러운 솔로 안쪽·바깥쪽·테두리를 나눠 짧게 문지르고, 싱크볼의 보이는 자국도 부드러운 천으로 닦아요.');
insert into kb.step_source_links(procedure_version_id, step_no, source_version_id, section_locator, support_note) values ('8a39669d-51cb-584f-bb83-fa042f4af717'::uuid, 4, 'fe74460b-c981-53e9-9c4b-0f06aa60b56a'::uuid, 'verified-scope:cdc_home_cleaning', '검수자가 단계 문안과 출처의 적용 범위를 대조함');
insert into kb.step_source_links(procedure_version_id, step_no, source_version_id, section_locator, support_note) values ('8a39669d-51cb-584f-bb83-fa042f4af717'::uuid, 4, '213afb63-6240-58be-9627-a9d2db71ad8a'::uuid, 'verified-scope:aci_hard_surfaces', '검수자가 단계 문안과 출처의 적용 범위를 대조함');
insert into kb.procedure_steps(id, procedure_version_id, step_no, stage_code, instruction, detail, completion_cue, caution, speech_text) values ('328f376b-75af-5a30-8bc2-bd5158daccb2'::uuid, '8a39669d-51cb-584f-bb83-fa042f4af717'::uuid, 5, 'rinse', '깨끗한 물로 망 구멍과 싱크볼을 충분히 헹궈요.', '거름망을 돌려가며 망 구멍 사이에 닦인 잔여물이 남지 않을 때까지 헹구고 싱크볼도 깨끗한 물로 마무리해요.', '거름망과 싱크볼에 닦인 잔여물이 보이지 않아요.', null, '깨끗한 물로 망 구멍과 싱크볼을 충분히 헹궈요. 거름망을 돌려가며 망 구멍 사이에 닦인 잔여물이 남지 않을 때까지 헹구고 싱크볼도 깨끗한 물로 마무리해요.');
insert into kb.step_source_links(procedure_version_id, step_no, source_version_id, section_locator, support_note) values ('8a39669d-51cb-584f-bb83-fa042f4af717'::uuid, 5, 'fe74460b-c981-53e9-9c4b-0f06aa60b56a'::uuid, 'verified-scope:cdc_home_cleaning', '검수자가 단계 문안과 출처의 적용 범위를 대조함');
insert into kb.step_source_links(procedure_version_id, step_no, source_version_id, section_locator, support_note) values ('8a39669d-51cb-584f-bb83-fa042f4af717'::uuid, 5, '213afb63-6240-58be-9627-a9d2db71ad8a'::uuid, 'verified-scope:aci_hard_surfaces', '검수자가 단계 문안과 출처의 적용 범위를 대조함');
insert into kb.procedure_steps(id, procedure_version_id, step_no, stage_code, instruction, detail, completion_cue, caution, speech_text) values ('c8141876-e1d6-5d8e-ae61-c972deed6b5d'::uuid, '8a39669d-51cb-584f-bb83-fa042f4af717'::uuid, 6, 'dry', '물기를 닦고 거름망을 제자리에 놓아요.', '거름망과 싱크볼 가장자리의 물기를 마른 천으로 닦고, 거름망이 흔들리지 않게 원래 위치에 놓아요.', '거름망이 제자리에 있고 주변 물기가 제거됐어요.', null, '물기를 닦고 거름망을 제자리에 놓아요. 거름망과 싱크볼 가장자리의 물기를 마른 천으로 닦고, 거름망이 흔들리지 않게 원래 위치에 놓아요.');
insert into kb.step_source_links(procedure_version_id, step_no, source_version_id, section_locator, support_note) values ('8a39669d-51cb-584f-bb83-fa042f4af717'::uuid, 6, '789fb545-60ce-51e2-b513-d0a782645106'::uuid, 'verified-scope:aci_home_routine', '검수자가 단계 문안과 출처의 적용 범위를 대조함');
insert into kb.step_source_links(procedure_version_id, step_no, source_version_id, section_locator, support_note) values ('8a39669d-51cb-584f-bb83-fa042f4af717'::uuid, 6, '213afb63-6240-58be-9627-a9d2db71ad8a'::uuid, 'verified-scope:aci_hard_surfaces', '검수자가 단계 문안과 출처의 적용 범위를 대조함');
insert into kb.review_events(id, entity_type, entity_version_id, decision, reason, reviewer_ref, created_at) values ('903980f1-d69d-56d9-92dc-ca7b1239386f'::uuid, 'procedure_version', '8a39669d-51cb-584f-bb83-fa042f4af717'::uuid, 'approved', '단계 순서·출처 범위·안전 문구·실행 가능성 검수 완료', 'knowledge-editor-2026-08-25', '2026-08-25T06:00:00Z'::timestamptz);
insert into kb.procedures(id, procedure_key) values ('7426e102-819e-5277-808a-ea3563f81304'::uuid, 'sink-water-scale-v1');
insert into kb.procedure_versions(id, procedure_id, revision, status, locale, title, summary, required_step_count, content_hash) values ('693982d8-ef29-58d1-89bc-f9a6b06597cf'::uuid, '7426e102-819e-5277-808a-ea3563f81304'::uuid, 1, 'draft', 'ko-KR', '싱크대 수전의 물때 추정 흔적 청소', '수전 외부의 느슨한 먼지를 걷고 미지근한 물로 불린 뒤 부드럽게 닦아 물기를 남기지 않아요.', 6, '20fc1ceee4e887da4d987e9648b999679f16783ca598d80e38f7abe8768c8259');
insert into kb.procedure_steps(id, procedure_version_id, step_no, stage_code, instruction, detail, completion_cue, caution, speech_text) values ('32a4697f-cbaf-5ed0-b396-5303bb187df5'::uuid, '693982d8-ef29-58d1-89bc-f9a6b06597cf'::uuid, 1, 'prepare', '부드러운 천 두 장과 미지근한 물을 준비해요.', '젖은 천과 마른 천을 나누고 수전 주변 물건을 치워 손이 닿는 작은 면부터 시작해요.', '수전 주변이 비고 젖은 천과 마른 천이 준비됐어요.', null, '부드러운 천 두 장과 미지근한 물을 준비해요. 젖은 천과 마른 천을 나누고 수전 주변 물건을 치워 손이 닿는 작은 면부터 시작해요.');
insert into kb.step_source_links(procedure_version_id, step_no, source_version_id, section_locator, support_note) values ('693982d8-ef29-58d1-89bc-f9a6b06597cf'::uuid, 1, '789fb545-60ce-51e2-b513-d0a782645106'::uuid, 'verified-scope:aci_home_routine', '검수자가 단계 문안과 출처의 적용 범위를 대조함');
insert into kb.step_source_links(procedure_version_id, step_no, source_version_id, section_locator, support_note) values ('693982d8-ef29-58d1-89bc-f9a6b06597cf'::uuid, 1, '213afb63-6240-58be-9627-a9d2db71ad8a'::uuid, 'verified-scope:aci_hard_surfaces', '검수자가 단계 문안과 출처의 적용 범위를 대조함');
insert into kb.procedure_steps(id, procedure_version_id, step_no, stage_code, instruction, detail, completion_cue, caution, speech_text) values ('f2c7c2bc-47e6-5a22-ab95-4c5054e412f1'::uuid, '693982d8-ef29-58d1-89bc-f9a6b06597cf'::uuid, 2, 'preclean', '마른 천으로 느슨한 먼지와 물기를 먼저 걷어요.', '수전의 위쪽부터 아래쪽으로 가볍게 닦아 표면에 남은 먼지와 물방울을 제거해요.', '수전에 느슨한 먼지와 고인 물방울이 없어요.', null, '마른 천으로 느슨한 먼지와 물기를 먼저 걷어요. 수전의 위쪽부터 아래쪽으로 가볍게 닦아 표면에 남은 먼지와 물방울을 제거해요.');
insert into kb.step_source_links(procedure_version_id, step_no, source_version_id, section_locator, support_note) values ('693982d8-ef29-58d1-89bc-f9a6b06597cf'::uuid, 2, 'd153c12d-48a4-5322-aa9e-fae37414889b'::uuid, 'verified-scope:me_indoor_air', '검수자가 단계 문안과 출처의 적용 범위를 대조함');
insert into kb.step_source_links(procedure_version_id, step_no, source_version_id, section_locator, support_note) values ('693982d8-ef29-58d1-89bc-f9a6b06597cf'::uuid, 2, '213afb63-6240-58be-9627-a9d2db71ad8a'::uuid, 'verified-scope:aci_hard_surfaces', '검수자가 단계 문안과 출처의 적용 범위를 대조함');
insert into kb.procedure_steps(id, procedure_version_id, step_no, stage_code, instruction, detail, completion_cue, caution, speech_text) values ('47407e0b-0324-5017-8860-c8d40163ab07'::uuid, '693982d8-ef29-58d1-89bc-f9a6b06597cf'::uuid, 3, 'act', '미지근한 물에 적신 천을 물때 위에 잠시 올려요.', '천의 물기를 짠 뒤 하얀 자국이 보이는 작은 면을 덮어 굳은 흔적이 부드러워지게 해요.', '천이 자국을 덮고 물이 주변으로 흐르지 않아요.', '코팅 여부를 모르면 눈에 띄지 않는 작은 곳부터 확인해요.', '미지근한 물에 적신 천을 물때 위에 잠시 올려요. 천의 물기를 짠 뒤 하얀 자국이 보이는 작은 면을 덮어 굳은 흔적이 부드러워지게 해요.');
insert into kb.step_source_links(procedure_version_id, step_no, source_version_id, section_locator, support_note) values ('693982d8-ef29-58d1-89bc-f9a6b06597cf'::uuid, 3, 'fe74460b-c981-53e9-9c4b-0f06aa60b56a'::uuid, 'verified-scope:cdc_home_cleaning', '검수자가 단계 문안과 출처의 적용 범위를 대조함');
insert into kb.step_source_links(procedure_version_id, step_no, source_version_id, section_locator, support_note) values ('693982d8-ef29-58d1-89bc-f9a6b06597cf'::uuid, 3, '213afb63-6240-58be-9627-a9d2db71ad8a'::uuid, 'verified-scope:aci_hard_surfaces', '검수자가 단계 문안과 출처의 적용 범위를 대조함');
insert into kb.procedure_steps(id, procedure_version_id, step_no, stage_code, instruction, detail, completion_cue, caution, speech_text) values ('e159e29e-4673-5138-841d-5f930b0f8261'::uuid, '693982d8-ef29-58d1-89bc-f9a6b06597cf'::uuid, 4, 'act', '부드러워진 자국을 천의 깨끗한 면으로 닦아요.', '강하게 긁지 말고 짧게 여러 번 닦으며, 자국이 천에 묻으면 깨끗한 면으로 바꿔요.', '선택한 작은 면의 느슨해진 자국이 닦였어요.', '표면 변화가 보이면 더 문지르지 않아요.', '부드러워진 자국을 천의 깨끗한 면으로 닦아요. 강하게 긁지 말고 짧게 여러 번 닦으며, 자국이 천에 묻으면 깨끗한 면으로 바꿔요.');
insert into kb.step_source_links(procedure_version_id, step_no, source_version_id, section_locator, support_note) values ('693982d8-ef29-58d1-89bc-f9a6b06597cf'::uuid, 4, '213afb63-6240-58be-9627-a9d2db71ad8a'::uuid, 'verified-scope:aci_hard_surfaces', '검수자가 단계 문안과 출처의 적용 범위를 대조함');
insert into kb.procedure_steps(id, procedure_version_id, step_no, stage_code, instruction, detail, completion_cue, caution, speech_text) values ('d26bbca2-9c8e-5614-a0d5-439d01cfe12d'::uuid, '693982d8-ef29-58d1-89bc-f9a6b06597cf'::uuid, 5, 'rinse', '깨끗한 물을 묻힌 새 천으로 한 번 더 닦아요.', '수전 연결부에 물이 흐르지 않도록 천의 물기를 꼭 짜고 닦은 면을 고르게 훑어요.', '닦은 면에 보이는 잔여물이 없어요.', null, '깨끗한 물을 묻힌 새 천으로 한 번 더 닦아요. 수전 연결부에 물이 흐르지 않도록 천의 물기를 꼭 짜고 닦은 면을 고르게 훑어요.');
insert into kb.step_source_links(procedure_version_id, step_no, source_version_id, section_locator, support_note) values ('693982d8-ef29-58d1-89bc-f9a6b06597cf'::uuid, 5, '213afb63-6240-58be-9627-a9d2db71ad8a'::uuid, 'verified-scope:aci_hard_surfaces', '검수자가 단계 문안과 출처의 적용 범위를 대조함');
insert into kb.procedure_steps(id, procedure_version_id, step_no, stage_code, instruction, detail, completion_cue, caution, speech_text) values ('4fd2bdd2-5a3b-506e-85b5-c813f3d9b0ac'::uuid, '693982d8-ef29-58d1-89bc-f9a6b06597cf'::uuid, 6, 'dry', '마른 천으로 수전과 주변 물기를 완전히 제거해요.', '수전 본체와 밑동, 싱크대 가장자리를 눌러 닦아 물방울이 남지 않게 해요.', '수전 외부와 밑동이 마른 상태예요.', null, '마른 천으로 수전과 주변 물기를 완전히 제거해요. 수전 본체와 밑동, 싱크대 가장자리를 눌러 닦아 물방울이 남지 않게 해요.');
insert into kb.step_source_links(procedure_version_id, step_no, source_version_id, section_locator, support_note) values ('693982d8-ef29-58d1-89bc-f9a6b06597cf'::uuid, 6, '789fb545-60ce-51e2-b513-d0a782645106'::uuid, 'verified-scope:aci_home_routine', '검수자가 단계 문안과 출처의 적용 범위를 대조함');
insert into kb.step_source_links(procedure_version_id, step_no, source_version_id, section_locator, support_note) values ('693982d8-ef29-58d1-89bc-f9a6b06597cf'::uuid, 6, '213afb63-6240-58be-9627-a9d2db71ad8a'::uuid, 'verified-scope:aci_hard_surfaces', '검수자가 단계 문안과 출처의 적용 범위를 대조함');
insert into kb.review_events(id, entity_type, entity_version_id, decision, reason, reviewer_ref, created_at) values ('36ac3ad6-06ff-531e-904c-5ac9f8441235'::uuid, 'procedure_version', '693982d8-ef29-58d1-89bc-f9a6b06597cf'::uuid, 'approved', '단계 순서·출처 범위·안전 문구·실행 가능성 검수 완료', 'knowledge-editor-2026-08-25', '2026-08-25T06:00:00Z'::timestamptz);
insert into kb.procedures(id, procedure_key) values ('0ae17928-c36d-5283-b9ae-f88fb9dedf59'::uuid, 'soft-surface-sofa-v1');
insert into kb.procedure_versions(id, procedure_id, revision, status, locale, title, summary, required_step_count, content_hash) values ('d0865080-47d1-5d81-a73c-44531bcf3c26'::uuid, '0ae17928-c36d-5283-b9ae-f88fb9dedf59'::uuid, 1, 'draft', 'ko-KR', '소파 표면과 접근 가능한 틈 청소', '관리 라벨을 먼저 확인하고 쿠션 틈의 마른 먼지를 제거한 뒤 허용된 범위만 작은 곳부터 닦아요.', 5, '4885d1cc924a7b1ddefa8a13479a559cf2d54a7c7588ef8fe9c6a520cb3e2089');
insert into kb.procedure_steps(id, procedure_version_id, step_no, stage_code, instruction, detail, completion_cue, caution, speech_text) values ('394162bc-a588-56f6-91ac-aef25821b431'::uuid, 'd0865080-47d1-5d81-a73c-44531bcf3c26'::uuid, 1, 'prepare', '소파 관리 라벨과 분리 가능한 커버를 확인해요.', '라벨에서 세탁·물 사용 가능 여부를 확인하고, 확인되지 않으면 먼저 마른 청소 범위만 진행해요.', '관리 라벨을 확인했거나 마른 청소만 하기로 정했어요.', '재질을 사진만 보고 추정하지 않아요.', '소파 관리 라벨과 분리 가능한 커버를 확인해요. 라벨에서 세탁·물 사용 가능 여부를 확인하고, 확인되지 않으면 먼저 마른 청소 범위만 진행해요.');
insert into kb.step_source_links(procedure_version_id, step_no, source_version_id, section_locator, support_note) values ('d0865080-47d1-5d81-a73c-44531bcf3c26'::uuid, 1, 'fe74460b-c981-53e9-9c4b-0f06aa60b56a'::uuid, 'verified-scope:cdc_home_cleaning', '검수자가 단계 문안과 출처의 적용 범위를 대조함');
insert into kb.procedure_steps(id, procedure_version_id, step_no, stage_code, instruction, detail, completion_cue, caution, speech_text) values ('79c851a7-efd0-5cbb-9c8a-2b468f39e671'::uuid, 'd0865080-47d1-5d81-a73c-44531bcf3c26'::uuid, 2, 'preclean', '소파 위 물건과 쿠션을 잠시 옮겨요.', '리모컨·책·담요를 제자리에 두고 쿠션은 순서를 기억할 수 있게 가까운 곳에 세워요.', '좌석과 접근 가능한 틈이 보여요.', null, '소파 위 물건과 쿠션을 잠시 옮겨요. 리모컨·책·담요를 제자리에 두고 쿠션은 순서를 기억할 수 있게 가까운 곳에 세워요.');
insert into kb.step_source_links(procedure_version_id, step_no, source_version_id, section_locator, support_note) values ('d0865080-47d1-5d81-a73c-44531bcf3c26'::uuid, 2, '789fb545-60ce-51e2-b513-d0a782645106'::uuid, 'verified-scope:aci_home_routine', '검수자가 단계 문안과 출처의 적용 범위를 대조함');
insert into kb.procedure_steps(id, procedure_version_id, step_no, stage_code, instruction, detail, completion_cue, caution, speech_text) values ('0fc29647-732b-5c97-a2dd-acaf577111e4'::uuid, 'd0865080-47d1-5d81-a73c-44531bcf3c26'::uuid, 3, 'act', '틈과 표면의 마른 먼지를 천천히 제거해요.', '청소기 틈새 도구나 부드러운 브러시를 사용해 쿠션 아래와 봉제선 방향으로 먼지를 걷어요.', '보이는 부스러기와 느슨한 먼지가 줄었어요.', '천을 잡아당기거나 틈 안쪽을 억지로 분해하지 않아요.', '틈과 표면의 마른 먼지를 천천히 제거해요. 청소기 틈새 도구나 부드러운 브러시를 사용해 쿠션 아래와 봉제선 방향으로 먼지를 걷어요.');
insert into kb.step_source_links(procedure_version_id, step_no, source_version_id, section_locator, support_note) values ('d0865080-47d1-5d81-a73c-44531bcf3c26'::uuid, 3, 'fe74460b-c981-53e9-9c4b-0f06aa60b56a'::uuid, 'verified-scope:cdc_home_cleaning', '검수자가 단계 문안과 출처의 적용 범위를 대조함');
insert into kb.procedure_steps(id, procedure_version_id, step_no, stage_code, instruction, detail, completion_cue, caution, speech_text) values ('34034aea-71c1-5785-9bc2-5980385790d1'::uuid, 'd0865080-47d1-5d81-a73c-44531bcf3c26'::uuid, 4, 'act', '라벨이 허용한 경우에만 작은 곳부터 닦아요.', '물 사용이 허용된 커버라면 물기를 꼭 짠 천으로 눈에 띄지 않는 곳을 먼저 눌러 닦고 번짐을 확인해요.', '작은 시험 구역에 번짐이나 색 변화가 없어요.', '색이 묻어나오면 바로 멈춰요.', '라벨이 허용한 경우에만 작은 곳부터 닦아요. 물 사용이 허용된 커버라면 물기를 꼭 짠 천으로 눈에 띄지 않는 곳을 먼저 눌러 닦고 번짐을 확인해요.');
insert into kb.step_source_links(procedure_version_id, step_no, source_version_id, section_locator, support_note) values ('d0865080-47d1-5d81-a73c-44531bcf3c26'::uuid, 4, 'fe74460b-c981-53e9-9c4b-0f06aa60b56a'::uuid, 'verified-scope:cdc_home_cleaning', '검수자가 단계 문안과 출처의 적용 범위를 대조함');
insert into kb.step_source_links(procedure_version_id, step_no, source_version_id, section_locator, support_note) values ('d0865080-47d1-5d81-a73c-44531bcf3c26'::uuid, 4, '213afb63-6240-58be-9627-a9d2db71ad8a'::uuid, 'verified-scope:aci_hard_surfaces', '검수자가 단계 문안과 출처의 적용 범위를 대조함');
insert into kb.procedure_steps(id, procedure_version_id, step_no, stage_code, instruction, detail, completion_cue, caution, speech_text) values ('0252d3aa-223a-5416-8883-d3cc452810e4'::uuid, 'd0865080-47d1-5d81-a73c-44531bcf3c26'::uuid, 5, 'dry', '완전히 마른 뒤 쿠션을 돌려놓아요.', '젖은 부분이 있다면 공기가 통하게 두고, 만졌을 때 습기가 없어진 뒤 쿠션과 담요를 제자리에 놓아요.', '소파가 마르고 쿠션이 제자리에 있어요.', null, '완전히 마른 뒤 쿠션을 돌려놓아요. 젖은 부분이 있다면 공기가 통하게 두고, 만졌을 때 습기가 없어진 뒤 쿠션과 담요를 제자리에 놓아요.');
insert into kb.step_source_links(procedure_version_id, step_no, source_version_id, section_locator, support_note) values ('d0865080-47d1-5d81-a73c-44531bcf3c26'::uuid, 5, 'fe74460b-c981-53e9-9c4b-0f06aa60b56a'::uuid, 'verified-scope:cdc_home_cleaning', '검수자가 단계 문안과 출처의 적용 범위를 대조함');
insert into kb.review_events(id, entity_type, entity_version_id, decision, reason, reviewer_ref, created_at) values ('119d5be0-af5b-5fdd-a002-dae308fb7f3f'::uuid, 'procedure_version', 'd0865080-47d1-5d81-a73c-44531bcf3c26'::uuid, 'approved', '단계 순서·출처 범위·안전 문구·실행 가능성 검수 완료', 'knowledge-editor-2026-08-25', '2026-08-25T06:00:00Z'::timestamptz);
