insert into kb.procedure_versions(id, procedure_id, revision, status, locale, title, summary, required_step_count, content_hash) values ('846a5476-9be6-5b57-802d-2887efe346a0'::uuid, '2769b22d-4904-5996-bdcc-f88c07fd67bd'::uuid, 1, 'draft', 'ko-KR', '침대 주변과 프레임 청소', '침구를 분리하고 접근 가능한 틈의 먼지를 제거한 뒤 프레임을 마른 방식부터 정리해요.', 5, 'f0f8ce9ca790969ecbc04df20ebea1d1caa5bdca86f53f82694a3ffc0b323b4f');
insert into kb.procedure_steps(id, procedure_version_id, step_no, stage_code, instruction, detail, completion_cue, caution, speech_text) values ('9dcd2d56-eb3c-59bf-b2b0-e90883167a17'::uuid, '846a5476-9be6-5b57-802d-2887efe346a0'::uuid, 1, 'prepare', '침대 위 물건과 침구를 구분해요.', '전자기기와 책은 제자리에 두고, 세탁할 침구는 라벨을 확인하며 바구니에 따로 모아요.', '침대 위에는 청소할 면만 남았어요.', null, '침대 위 물건과 침구를 구분해요. 전자기기와 책은 제자리에 두고, 세탁할 침구는 라벨을 확인하며 바구니에 따로 모아요.');
insert into kb.step_source_links(procedure_version_id, step_no, source_version_id, section_locator, support_note) values ('846a5476-9be6-5b57-802d-2887efe346a0'::uuid, 1, 'fe74460b-c981-53e9-9c4b-0f06aa60b56a'::uuid, 'verified-scope:cdc_home_cleaning', '검수자가 단계 문안과 출처의 적용 범위를 대조함');
insert into kb.step_source_links(procedure_version_id, step_no, source_version_id, section_locator, support_note) values ('846a5476-9be6-5b57-802d-2887efe346a0'::uuid, 1, '789fb545-60ce-51e2-b513-d0a782645106'::uuid, 'verified-scope:aci_home_routine', '검수자가 단계 문안과 출처의 적용 범위를 대조함');
insert into kb.procedure_steps(id, procedure_version_id, step_no, stage_code, instruction, detail, completion_cue, caution, speech_text) values ('ea697928-fddc-562b-bfa9-16b291e3622a'::uuid, '846a5476-9be6-5b57-802d-2887efe346a0'::uuid, 2, 'preclean', '창문을 열거나 환기하며 마른 먼지를 확인해요.', '프레임 모서리와 침대 아래 접근 가능한 구역을 눈으로 확인하고 큰 물건부터 꺼내요.', '접근 가능한 모서리와 바닥이 보여요.', '무거운 침대를 혼자 옮기지 않아요.', '창문을 열거나 환기하며 마른 먼지를 확인해요. 프레임 모서리와 침대 아래 접근 가능한 구역을 눈으로 확인하고 큰 물건부터 꺼내요.');
insert into kb.step_source_links(procedure_version_id, step_no, source_version_id, section_locator, support_note) values ('846a5476-9be6-5b57-802d-2887efe346a0'::uuid, 2, '789fb545-60ce-51e2-b513-d0a782645106'::uuid, 'verified-scope:aci_home_routine', '검수자가 단계 문안과 출처의 적용 범위를 대조함');
insert into kb.step_source_links(procedure_version_id, step_no, source_version_id, section_locator, support_note) values ('846a5476-9be6-5b57-802d-2887efe346a0'::uuid, 2, 'd153c12d-48a4-5322-aa9e-fae37414889b'::uuid, 'verified-scope:me_indoor_air', '검수자가 단계 문안과 출처의 적용 범위를 대조함');
insert into kb.procedure_steps(id, procedure_version_id, step_no, stage_code, instruction, detail, completion_cue, caution, speech_text) values ('87e64e77-cc3e-56b0-b789-15acf19381e7'::uuid, '846a5476-9be6-5b57-802d-2887efe346a0'::uuid, 3, 'act', '청소기나 부드러운 브러시로 먼지를 걷어요.', '매트리스 표면, 프레임 틈, 침대 아래 가장자리 순으로 천천히 이동하며 마른 먼지를 제거해요.', '보이는 먼지와 부스러기가 제거됐어요.', '매트리스 관리 라벨과 다른 습식 청소를 추가하지 않아요.', '청소기나 부드러운 브러시로 먼지를 걷어요. 매트리스 표면, 프레임 틈, 침대 아래 가장자리 순으로 천천히 이동하며 마른 먼지를 제거해요.');
insert into kb.step_source_links(procedure_version_id, step_no, source_version_id, section_locator, support_note) values ('846a5476-9be6-5b57-802d-2887efe346a0'::uuid, 3, 'fe74460b-c981-53e9-9c4b-0f06aa60b56a'::uuid, 'verified-scope:cdc_home_cleaning', '검수자가 단계 문안과 출처의 적용 범위를 대조함');
insert into kb.procedure_steps(id, procedure_version_id, step_no, stage_code, instruction, detail, completion_cue, caution, speech_text) values ('876a0a58-d67e-55ad-9a09-b16f2bb2cbd2'::uuid, '846a5476-9be6-5b57-802d-2887efe346a0'::uuid, 4, 'act', '프레임은 마른 부드러운 천부터 사용해요.', '재질 관리 방법을 모르면 마른 천으로 한 방향씩 닦고, 물 사용은 공식 관리 안내가 확인될 때만 해요.', '프레임의 느슨한 먼지가 닦였어요.', '도장이나 코팅 변화가 보이면 멈춰요.', '프레임은 마른 부드러운 천부터 사용해요. 재질 관리 방법을 모르면 마른 천으로 한 방향씩 닦고, 물 사용은 공식 관리 안내가 확인될 때만 해요.');
insert into kb.step_source_links(procedure_version_id, step_no, source_version_id, section_locator, support_note) values ('846a5476-9be6-5b57-802d-2887efe346a0'::uuid, 4, 'fe74460b-c981-53e9-9c4b-0f06aa60b56a'::uuid, 'verified-scope:cdc_home_cleaning', '검수자가 단계 문안과 출처의 적용 범위를 대조함');
insert into kb.step_source_links(procedure_version_id, step_no, source_version_id, section_locator, support_note) values ('846a5476-9be6-5b57-802d-2887efe346a0'::uuid, 4, '213afb63-6240-58be-9627-a9d2db71ad8a'::uuid, 'verified-scope:aci_hard_surfaces', '검수자가 단계 문안과 출처의 적용 범위를 대조함');
insert into kb.procedure_steps(id, procedure_version_id, step_no, stage_code, instruction, detail, completion_cue, caution, speech_text) values ('d49f66f5-f05d-5406-a2ac-5073cdda696b'::uuid, '846a5476-9be6-5b57-802d-2887efe346a0'::uuid, 5, 'finish', '청소 도구를 비우고 마른 침구만 돌려놓아요.', '먼지통과 브러시를 정리하고, 세탁한 침구는 완전히 마른 뒤 다시 깔아요.', '침대 주변이 정리되고 젖은 침구가 남지 않았어요.', null, '청소 도구를 비우고 마른 침구만 돌려놓아요. 먼지통과 브러시를 정리하고, 세탁한 침구는 완전히 마른 뒤 다시 깔아요.');
insert into kb.step_source_links(procedure_version_id, step_no, source_version_id, section_locator, support_note) values ('846a5476-9be6-5b57-802d-2887efe346a0'::uuid, 5, 'fe74460b-c981-53e9-9c4b-0f06aa60b56a'::uuid, 'verified-scope:cdc_home_cleaning', '검수자가 단계 문안과 출처의 적용 범위를 대조함');
insert into kb.review_events(id, entity_type, entity_version_id, decision, reason, reviewer_ref, created_at) values ('7613b199-55db-5521-9291-c6677a71e750'::uuid, 'procedure_version', '846a5476-9be6-5b57-802d-2887efe346a0'::uuid, 'approved', '단계 순서·출처 범위·안전 문구·실행 가능성 검수 완료', 'knowledge-editor-2026-08-25', '2026-08-25T06:00:00Z'::timestamptz);
insert into kb.procedures(id, procedure_key) values ('22b0e146-520c-57c6-982a-e67af70fd9ee'::uuid, 'shoe-cabinet-clean-v1');
insert into kb.procedure_versions(id, procedure_id, revision, status, locale, title, summary, required_step_count, content_hash) values ('05bcdc8e-4ef9-5034-b1ba-0a25e4e4f5b5'::uuid, '22b0e146-520c-57c6-982a-e67af70fd9ee'::uuid, 1, 'draft', 'ko-KR', '신발장 선반과 현관 먼지 청소', '신발을 구역별로 꺼내고 모래와 먼지를 먼저 걷은 뒤 선반을 작은 면씩 닦아 말려요.', 5, 'edcf1769c2764a0db50dd78dfa3c2c57ac7b015e70edad75f1be4e218df9e67f');
insert into kb.procedure_steps(id, procedure_version_id, step_no, stage_code, instruction, detail, completion_cue, caution, speech_text) values ('b6cc7435-7dea-55c6-a884-67cb44b63f8a'::uuid, '05bcdc8e-4ef9-5034-b1ba-0a25e4e4f5b5'::uuid, 1, 'prepare', '문이 닫히지 않게 고정하고 한 선반만 정해요.', '통로를 막지 않는 위치에 신발을 둘 종이나 바구니를 펴고 가장 아래 또는 위 선반 하나부터 시작해요.', '청소할 한 선반과 임시 신발 자리가 정해졌어요.', '현관 통로와 문 앞을 막지 않아요.', '문이 닫히지 않게 고정하고 한 선반만 정해요. 통로를 막지 않는 위치에 신발을 둘 종이나 바구니를 펴고 가장 아래 또는 위 선반 하나부터 시작해요.');
insert into kb.step_source_links(procedure_version_id, step_no, source_version_id, section_locator, support_note) values ('05bcdc8e-4ef9-5034-b1ba-0a25e4e4f5b5'::uuid, 1, '789fb545-60ce-51e2-b513-d0a782645106'::uuid, 'verified-scope:aci_home_routine', '검수자가 단계 문안과 출처의 적용 범위를 대조함');
insert into kb.procedure_steps(id, procedure_version_id, step_no, stage_code, instruction, detail, completion_cue, caution, speech_text) values ('a461bea9-bd5b-53fa-85c1-294bdf0a33e7'::uuid, '05bcdc8e-4ef9-5034-b1ba-0a25e4e4f5b5'::uuid, 2, 'preclean', '신발을 짝별로 꺼내 상태를 확인해요.', '자주 신는 것과 보관할 것을 나누고 젖은 신발은 선반에 다시 넣지 말고 통풍되는 곳에 따로 둬요.', '선반이 비고 젖은 신발이 분리됐어요.', null, '신발을 짝별로 꺼내 상태를 확인해요. 자주 신는 것과 보관할 것을 나누고 젖은 신발은 선반에 다시 넣지 말고 통풍되는 곳에 따로 둬요.');
insert into kb.step_source_links(procedure_version_id, step_no, source_version_id, section_locator, support_note) values ('05bcdc8e-4ef9-5034-b1ba-0a25e4e4f5b5'::uuid, 2, '789fb545-60ce-51e2-b513-d0a782645106'::uuid, 'verified-scope:aci_home_routine', '검수자가 단계 문안과 출처의 적용 범위를 대조함');
insert into kb.procedure_steps(id, procedure_version_id, step_no, stage_code, instruction, detail, completion_cue, caution, speech_text) values ('b4ac3630-d7c2-5ebb-9e1b-84609a86d674'::uuid, '05bcdc8e-4ef9-5034-b1ba-0a25e4e4f5b5'::uuid, 3, 'act', '마른 솔이나 천으로 모래와 먼지를 먼저 걷어요.', '선반 안쪽에서 바깥쪽으로 움직이며 모래를 한곳에 모아 봉투에 버려요.', '선반에 느슨한 모래와 먼지가 없어요.', '먼지를 공중으로 세게 털지 않아요.', '마른 솔이나 천으로 모래와 먼지를 먼저 걷어요. 선반 안쪽에서 바깥쪽으로 움직이며 모래를 한곳에 모아 봉투에 버려요.');
insert into kb.step_source_links(procedure_version_id, step_no, source_version_id, section_locator, support_note) values ('05bcdc8e-4ef9-5034-b1ba-0a25e4e4f5b5'::uuid, 3, 'd153c12d-48a4-5322-aa9e-fae37414889b'::uuid, 'verified-scope:me_indoor_air', '검수자가 단계 문안과 출처의 적용 범위를 대조함');
insert into kb.step_source_links(procedure_version_id, step_no, source_version_id, section_locator, support_note) values ('05bcdc8e-4ef9-5034-b1ba-0a25e4e4f5b5'::uuid, 3, '789fb545-60ce-51e2-b513-d0a782645106'::uuid, 'verified-scope:aci_home_routine', '검수자가 단계 문안과 출처의 적용 범위를 대조함');
insert into kb.procedure_steps(id, procedure_version_id, step_no, stage_code, instruction, detail, completion_cue, caution, speech_text) values ('bd8ebfad-a796-5ff8-be81-0b08b651640c'::uuid, '05bcdc8e-4ef9-5034-b1ba-0a25e4e4f5b5'::uuid, 4, 'act', '물기를 꼭 짠 천으로 작은 면부터 닦아요.', '눈에 띄지 않는 모서리를 먼저 닦고 이상이 없으면 선반 전체를 한 방향으로 닦아요.', '선반 표면의 보이는 자국이 닦였어요.', '표면이 부풀거나 색이 변하면 멈춰요.', '물기를 꼭 짠 천으로 작은 면부터 닦아요. 눈에 띄지 않는 모서리를 먼저 닦고 이상이 없으면 선반 전체를 한 방향으로 닦아요.');
insert into kb.step_source_links(procedure_version_id, step_no, source_version_id, section_locator, support_note) values ('05bcdc8e-4ef9-5034-b1ba-0a25e4e4f5b5'::uuid, 4, 'fe74460b-c981-53e9-9c4b-0f06aa60b56a'::uuid, 'verified-scope:cdc_home_cleaning', '검수자가 단계 문안과 출처의 적용 범위를 대조함');
insert into kb.step_source_links(procedure_version_id, step_no, source_version_id, section_locator, support_note) values ('05bcdc8e-4ef9-5034-b1ba-0a25e4e4f5b5'::uuid, 4, '213afb63-6240-58be-9627-a9d2db71ad8a'::uuid, 'verified-scope:aci_hard_surfaces', '검수자가 단계 문안과 출처의 적용 범위를 대조함');
insert into kb.procedure_steps(id, procedure_version_id, step_no, stage_code, instruction, detail, completion_cue, caution, speech_text) values ('db97ff56-3a63-545f-9d88-1f828f84ced8'::uuid, '05bcdc8e-4ef9-5034-b1ba-0a25e4e4f5b5'::uuid, 5, 'dry', '문을 열어 선반을 완전히 말린 뒤 신발을 넣어요.', '마른 천으로 모서리 물기를 닦고 습기가 없어진 것을 확인한 뒤 자주 신는 신발부터 제자리에 둬요.', '선반이 마르고 신발이 통로를 막지 않아요.', null, '문을 열어 선반을 완전히 말린 뒤 신발을 넣어요. 마른 천으로 모서리 물기를 닦고 습기가 없어진 것을 확인한 뒤 자주 신는 신발부터 제자리에 둬요.');
insert into kb.step_source_links(procedure_version_id, step_no, source_version_id, section_locator, support_note) values ('05bcdc8e-4ef9-5034-b1ba-0a25e4e4f5b5'::uuid, 5, '789fb545-60ce-51e2-b513-d0a782645106'::uuid, 'verified-scope:aci_home_routine', '검수자가 단계 문안과 출처의 적용 범위를 대조함');
insert into kb.review_events(id, entity_type, entity_version_id, decision, reason, reviewer_ref, created_at) values ('124e27be-e3a4-5c68-8339-c31fd07da922'::uuid, 'procedure_version', '05bcdc8e-4ef9-5034-b1ba-0a25e4e4f5b5'::uuid, 'approved', '단계 순서·출처 범위·안전 문구·실행 가능성 검수 완료', 'knowledge-editor-2026-08-25', '2026-08-25T06:00:00Z'::timestamptz);
insert into kb.procedures(id, procedure_key) values ('c10bc2a9-9730-5965-a525-c6b654bd8785'::uuid, 'bathroom-general-clean-v1');
insert into kb.procedure_versions(id, procedure_id, revision, status, locale, title, summary, required_step_count, content_hash) values ('9c5d8d05-f406-5d67-853b-af590c403009'::uuid, 'c10bc2a9-9730-5965-a525-c6b654bd8785'::uuid, 1, 'draft', 'ko-KR', '욕실 기본 청소', '환기하고 큰 이물질을 제거한 뒤 물로 헹굴 수 있는 표면을 위에서 아래로 닦고 충분히 말려요.', 6, 'e69a95accd276e69aacde6a114f021c60a249a8caf312790e979c1dde5f23d44');
insert into kb.procedure_steps(id, procedure_version_id, step_no, stage_code, instruction, detail, completion_cue, caution, speech_text) values ('91ca145d-42f9-5fa1-ac50-b3312da680a9'::uuid, '9c5d8d05-f406-5d67-853b-af590c403009'::uuid, 1, 'prepare', '문을 열고 환풍기를 켜요.', '욕실 문이나 창을 열고 배기팬을 켠 뒤 바닥의 미끄러운 물건과 청소에 방해되는 용품을 치워요.', '환기가 시작되고 이동 경로가 비었어요.', '젖은 바닥에서 서두르지 않아요.', '문을 열고 환풍기를 켜요. 욕실 문이나 창을 열고 배기팬을 켠 뒤 바닥의 미끄러운 물건과 청소에 방해되는 용품을 치워요.');
insert into kb.step_source_links(procedure_version_id, step_no, source_version_id, section_locator, support_note) values ('9c5d8d05-f406-5d67-853b-af590c403009'::uuid, 1, 'd153c12d-48a4-5322-aa9e-fae37414889b'::uuid, 'verified-scope:me_indoor_air', '검수자가 단계 문안과 출처의 적용 범위를 대조함');
insert into kb.step_source_links(procedure_version_id, step_no, source_version_id, section_locator, support_note) values ('9c5d8d05-f406-5d67-853b-af590c403009'::uuid, 1, 'e25aadb2-c343-5775-81f2-3dec47720952'::uuid, 'verified-scope:lh_home_ventilation', '검수자가 단계 문안과 출처의 적용 범위를 대조함');
insert into kb.procedure_steps(id, procedure_version_id, step_no, stage_code, instruction, detail, completion_cue, caution, speech_text) values ('ac2836ed-e7ae-59c1-93a4-849c2e498dd8'::uuid, '9c5d8d05-f406-5d67-853b-af590c403009'::uuid, 2, 'protect', '장갑을 끼고 물에 젖으면 안 되는 물건을 밖으로 옮겨요.', '수건·휴대기기·전기용품을 욕실 밖에 두고, 장갑과 부드러운 천·솔을 준비해요.', '전기용품이 밖에 있고 장갑을 착용했어요.', null, '장갑을 끼고 물에 젖으면 안 되는 물건을 밖으로 옮겨요. 수건·휴대기기·전기용품을 욕실 밖에 두고, 장갑과 부드러운 천·솔을 준비해요.');
insert into kb.step_source_links(procedure_version_id, step_no, source_version_id, section_locator, support_note) values ('9c5d8d05-f406-5d67-853b-af590c403009'::uuid, 2, 'fe74460b-c981-53e9-9c4b-0f06aa60b56a'::uuid, 'verified-scope:cdc_home_cleaning', '검수자가 단계 문안과 출처의 적용 범위를 대조함');
insert into kb.procedure_steps(id, procedure_version_id, step_no, stage_code, instruction, detail, completion_cue, caution, speech_text) values ('2f4a7722-1260-5d3d-bf98-42515c0f8f30'::uuid, '9c5d8d05-f406-5d67-853b-af590c403009'::uuid, 3, 'preclean', '머리카락과 큰 이물질부터 제거해요.', '바닥과 배수구 덮개 주변의 머리카락·휴지를 집어 봉투에 버리고 배수구로 밀어 넣지 않아요.', '바닥과 배수구 주변에 큰 이물질이 없어요.', '배수구 역류가 보이면 사용을 멈춰요.', '머리카락과 큰 이물질부터 제거해요. 바닥과 배수구 덮개 주변의 머리카락·휴지를 집어 봉투에 버리고 배수구로 밀어 넣지 않아요.');
insert into kb.step_source_links(procedure_version_id, step_no, source_version_id, section_locator, support_note) values ('9c5d8d05-f406-5d67-853b-af590c403009'::uuid, 3, 'fe74460b-c981-53e9-9c4b-0f06aa60b56a'::uuid, 'verified-scope:cdc_home_cleaning', '검수자가 단계 문안과 출처의 적용 범위를 대조함');
insert into kb.step_source_links(procedure_version_id, step_no, source_version_id, section_locator, support_note) values ('9c5d8d05-f406-5d67-853b-af590c403009'::uuid, 3, 'f0f1a866-d5d2-50b8-92a8-257db1074c8f'::uuid, 'verified-scope:epa_mold_home', '검수자가 단계 문안과 출처의 적용 범위를 대조함');
insert into kb.procedure_steps(id, procedure_version_id, step_no, stage_code, instruction, detail, completion_cue, caution, speech_text) values ('c961bdbe-5901-568a-8bdb-6237a3a6876b'::uuid, '9c5d8d05-f406-5d67-853b-af590c403009'::uuid, 4, 'act', '미지근한 물로 작은 구역부터 부드럽게 닦아요.', '물로 헹굴 수 있는 단단한 표면을 위쪽에서 아래쪽 순서로 나누고, 물에 적신 부드러운 천이나 솔로 보이는 자국을 닦아요.', '선택한 한 구역의 보이는 자국이 닦였어요.', '표면 변화가 보이면 더 문지르지 않아요.', '미지근한 물로 작은 구역부터 부드럽게 닦아요. 물로 헹굴 수 있는 단단한 표면을 위쪽에서 아래쪽 순서로 나누고, 물에 적신 부드러운 천이나 솔로 보이는 자국을 닦아요.');
insert into kb.step_source_links(procedure_version_id, step_no, source_version_id, section_locator, support_note) values ('9c5d8d05-f406-5d67-853b-af590c403009'::uuid, 4, 'fe74460b-c981-53e9-9c4b-0f06aa60b56a'::uuid, 'verified-scope:cdc_home_cleaning', '검수자가 단계 문안과 출처의 적용 범위를 대조함');
insert into kb.step_source_links(procedure_version_id, step_no, source_version_id, section_locator, support_note) values ('9c5d8d05-f406-5d67-853b-af590c403009'::uuid, 4, '213afb63-6240-58be-9627-a9d2db71ad8a'::uuid, 'verified-scope:aci_hard_surfaces', '검수자가 단계 문안과 출처의 적용 범위를 대조함');
insert into kb.procedure_steps(id, procedure_version_id, step_no, stage_code, instruction, detail, completion_cue, caution, speech_text) values ('4fd8428c-57c3-58f1-ad77-ec894b3ca6f5'::uuid, '9c5d8d05-f406-5d67-853b-af590c403009'::uuid, 5, 'rinse', '깨끗한 물로 닦은 구역을 충분히 헹궈요.', '위쪽에서 아래쪽으로 물을 흘려 느슨해진 잔여물이 남지 않게 해요.', '닦은 구역에 느슨한 잔여물이 보이지 않아요.', '물이 전기 설비나 문밖으로 흐르지 않게 해요.', '깨끗한 물로 닦은 구역을 충분히 헹궈요. 위쪽에서 아래쪽으로 물을 흘려 느슨해진 잔여물이 남지 않게 해요.');
insert into kb.step_source_links(procedure_version_id, step_no, source_version_id, section_locator, support_note) values ('9c5d8d05-f406-5d67-853b-af590c403009'::uuid, 5, '213afb63-6240-58be-9627-a9d2db71ad8a'::uuid, 'verified-scope:aci_hard_surfaces', '검수자가 단계 문안과 출처의 적용 범위를 대조함');
insert into kb.procedure_steps(id, procedure_version_id, step_no, stage_code, instruction, detail, completion_cue, caution, speech_text) values ('5c1870bf-cd41-5d0e-8b3a-23da85174714'::uuid, '9c5d8d05-f406-5d67-853b-af590c403009'::uuid, 6, 'dry', '물기를 제거하고 환기를 이어가요.', '스퀴지나 마른 천으로 벽·수전·바닥 가장자리의 물기를 제거하고 표면이 마를 때까지 환풍기를 켜 둬요.', '고인 물이 없고 표면이 마르기 시작했어요.', null, '물기를 제거하고 환기를 이어가요. 스퀴지나 마른 천으로 벽·수전·바닥 가장자리의 물기를 제거하고 표면이 마를 때까지 환풍기를 켜 둬요.');
insert into kb.step_source_links(procedure_version_id, step_no, source_version_id, section_locator, support_note) values ('9c5d8d05-f406-5d67-853b-af590c403009'::uuid, 6, '789fb545-60ce-51e2-b513-d0a782645106'::uuid, 'verified-scope:aci_home_routine', '검수자가 단계 문안과 출처의 적용 범위를 대조함');
insert into kb.step_source_links(procedure_version_id, step_no, source_version_id, section_locator, support_note) values ('9c5d8d05-f406-5d67-853b-af590c403009'::uuid, 6, 'd153c12d-48a4-5322-aa9e-fae37414889b'::uuid, 'verified-scope:me_indoor_air', '검수자가 단계 문안과 출처의 적용 범위를 대조함');
