insert into kb.procedure_versions(id, procedure_id, revision, status, locale, title, summary, required_step_count, content_hash) values ('6d0fb62a-12d9-5e4f-9dc4-bcd50fc01bef'::uuid, 'a4f9d351-5762-5b7d-a4cc-fea294ca37c6'::uuid, 1, 'draft', 'ko-KR', '욕실 물때 추정 흔적 청소', '환기와 보호를 먼저 하고 미지근한 물로 흔적을 불린 뒤 부드럽게 닦고 헹궈 완전히 말려요.', 6, 'c5f72e32939b1263c52e52eb77c17d41abe0f7ea91f2c1bef768daa4d85736e6');
insert into kb.procedure_steps(id, procedure_version_id, step_no, stage_code, instruction, detail, completion_cue, caution, speech_text) values ('c757655a-1058-598e-b831-d09a46ee0776'::uuid, '6d0fb62a-12d9-5e4f-9dc4-bcd50fc01bef'::uuid, 1, 'prepare', '문을 열고 환풍기를 켠 뒤 작은 구역을 정해요.', '욕실 전체가 아니라 수전이나 타일 한 면처럼 물때가 보이는 작은 구역 하나를 선택해요.', '환기가 시작되고 작업 구역이 정해졌어요.', null, '문을 열고 환풍기를 켠 뒤 작은 구역을 정해요. 욕실 전체가 아니라 수전이나 타일 한 면처럼 물때가 보이는 작은 구역 하나를 선택해요.');
insert into kb.step_source_links(procedure_version_id, step_no, source_version_id, section_locator, support_note) values ('6d0fb62a-12d9-5e4f-9dc4-bcd50fc01bef'::uuid, 1, 'd153c12d-48a4-5322-aa9e-fae37414889b'::uuid, 'verified-scope:me_indoor_air', '검수자가 단계 문안과 출처의 적용 범위를 대조함');
insert into kb.step_source_links(procedure_version_id, step_no, source_version_id, section_locator, support_note) values ('6d0fb62a-12d9-5e4f-9dc4-bcd50fc01bef'::uuid, 1, 'e25aadb2-c343-5775-81f2-3dec47720952'::uuid, 'verified-scope:lh_home_ventilation', '검수자가 단계 문안과 출처의 적용 범위를 대조함');
insert into kb.step_source_links(procedure_version_id, step_no, source_version_id, section_locator, support_note) values ('6d0fb62a-12d9-5e4f-9dc4-bcd50fc01bef'::uuid, 1, '789fb545-60ce-51e2-b513-d0a782645106'::uuid, 'verified-scope:aci_home_routine', '검수자가 단계 문안과 출처의 적용 범위를 대조함');
insert into kb.procedure_steps(id, procedure_version_id, step_no, stage_code, instruction, detail, completion_cue, caution, speech_text) values ('040bbb80-36b1-567d-968f-48e3c444c159'::uuid, '6d0fb62a-12d9-5e4f-9dc4-bcd50fc01bef'::uuid, 2, 'protect', '장갑을 끼고 부드러운 천 두 장을 준비해요.', '미지근한 물에 적실 천과 마지막에 말릴 천을 구분해 두고 거친 수세미는 치워요.', '장갑과 젖은 천·마른 천이 준비됐어요.', '연마 도구를 사용하지 않아요.', '장갑을 끼고 부드러운 천 두 장을 준비해요. 미지근한 물에 적실 천과 마지막에 말릴 천을 구분해 두고 거친 수세미는 치워요.');
insert into kb.step_source_links(procedure_version_id, step_no, source_version_id, section_locator, support_note) values ('6d0fb62a-12d9-5e4f-9dc4-bcd50fc01bef'::uuid, 2, '213afb63-6240-58be-9627-a9d2db71ad8a'::uuid, 'verified-scope:aci_hard_surfaces', '검수자가 단계 문안과 출처의 적용 범위를 대조함');
insert into kb.procedure_steps(id, procedure_version_id, step_no, stage_code, instruction, detail, completion_cue, caution, speech_text) values ('b95234c4-5346-5b31-9a0c-354fca72c1f9'::uuid, '6d0fb62a-12d9-5e4f-9dc4-bcd50fc01bef'::uuid, 3, 'act', '미지근한 물에 적신 천으로 흔적을 불려요.', '천의 물기를 짜서 하얀 물자국 위에 잠시 올리고 주변으로 물이 흐르지 않게 해요.', '젖은 천이 선택한 흔적만 덮고 있어요.', '코팅 여부를 모르면 작은 곳부터 확인해요.', '미지근한 물에 적신 천으로 흔적을 불려요. 천의 물기를 짜서 하얀 물자국 위에 잠시 올리고 주변으로 물이 흐르지 않게 해요.');
insert into kb.step_source_links(procedure_version_id, step_no, source_version_id, section_locator, support_note) values ('6d0fb62a-12d9-5e4f-9dc4-bcd50fc01bef'::uuid, 3, 'fe74460b-c981-53e9-9c4b-0f06aa60b56a'::uuid, 'verified-scope:cdc_home_cleaning', '검수자가 단계 문안과 출처의 적용 범위를 대조함');
insert into kb.step_source_links(procedure_version_id, step_no, source_version_id, section_locator, support_note) values ('6d0fb62a-12d9-5e4f-9dc4-bcd50fc01bef'::uuid, 3, '213afb63-6240-58be-9627-a9d2db71ad8a'::uuid, 'verified-scope:aci_hard_surfaces', '검수자가 단계 문안과 출처의 적용 범위를 대조함');
insert into kb.procedure_steps(id, procedure_version_id, step_no, stage_code, instruction, detail, completion_cue, caution, speech_text) values ('7869251c-3f91-5324-8f42-5948bacbbab7'::uuid, '6d0fb62a-12d9-5e4f-9dc4-bcd50fc01bef'::uuid, 4, 'act', '부드러워진 자국을 작은 원이나 한 방향으로 닦아요.', '강하게 긁지 말고 천의 깨끗한 면을 바꿔가며 선택한 구역을 짧게 여러 번 닦아요.', '느슨해진 물때가 천에 묻어나고 표면 변화가 없어요.', '벗겨짐이나 변색이 보이면 멈춰요.', '부드러워진 자국을 작은 원이나 한 방향으로 닦아요. 강하게 긁지 말고 천의 깨끗한 면을 바꿔가며 선택한 구역을 짧게 여러 번 닦아요.');
insert into kb.step_source_links(procedure_version_id, step_no, source_version_id, section_locator, support_note) values ('6d0fb62a-12d9-5e4f-9dc4-bcd50fc01bef'::uuid, 4, '213afb63-6240-58be-9627-a9d2db71ad8a'::uuid, 'verified-scope:aci_hard_surfaces', '검수자가 단계 문안과 출처의 적용 범위를 대조함');
insert into kb.procedure_steps(id, procedure_version_id, step_no, stage_code, instruction, detail, completion_cue, caution, speech_text) values ('979c1b56-b5b0-52d6-a338-e259087f6f28'::uuid, '6d0fb62a-12d9-5e4f-9dc4-bcd50fc01bef'::uuid, 5, 'rinse', '깨끗한 물로 닦은 구역을 헹궈요.', '새 천에 깨끗한 물을 묻혀 잔여물이 없게 닦거나, 물로 헹굴 수 있는 면은 위에서 아래로 가볍게 헹궈요.', '닦인 잔여물이 보이지 않아요.', null, '깨끗한 물로 닦은 구역을 헹궈요. 새 천에 깨끗한 물을 묻혀 잔여물이 없게 닦거나, 물로 헹굴 수 있는 면은 위에서 아래로 가볍게 헹궈요.');
insert into kb.step_source_links(procedure_version_id, step_no, source_version_id, section_locator, support_note) values ('6d0fb62a-12d9-5e4f-9dc4-bcd50fc01bef'::uuid, 5, '213afb63-6240-58be-9627-a9d2db71ad8a'::uuid, 'verified-scope:aci_hard_surfaces', '검수자가 단계 문안과 출처의 적용 범위를 대조함');
insert into kb.procedure_steps(id, procedure_version_id, step_no, stage_code, instruction, detail, completion_cue, caution, speech_text) values ('7564fffc-dfaf-5902-b324-e2d395e524e3'::uuid, '6d0fb62a-12d9-5e4f-9dc4-bcd50fc01bef'::uuid, 6, 'dry', '마른 천으로 물기를 제거하고 환기를 계속해요.', '수전 밑동·타일 모서리·줄눈 주변의 물기를 눌러 닦고 완전히 마를 때까지 환기해요.', '선택한 구역에 고인 물이 없어요.', null, '마른 천으로 물기를 제거하고 환기를 계속해요. 수전 밑동·타일 모서리·줄눈 주변의 물기를 눌러 닦고 완전히 마를 때까지 환기해요.');
