insert into kb.procedure_steps(id, procedure_version_id, step_no, stage_code, instruction, detail, completion_cue, caution, speech_text) values ('f625a0d1-ce52-58e0-a541-4ed9e2aca81a'::uuid, 'aa1d9588-4442-5df5-bdc5-c63e4e8a5c9e'::uuid, 1, 'prepare', '환기하고 비누막이 보이는 작은 구역을 정해요.', '샤워 벽이나 세면대 한쪽처럼 뿌연 흔적이 보이는 곳 하나만 선택하고 주변 용품을 치워요.', '환기가 시작되고 작은 작업 구역이 비었어요.', null, '환기하고 비누막이 보이는 작은 구역을 정해요. 샤워 벽이나 세면대 한쪽처럼 뿌연 흔적이 보이는 곳 하나만 선택하고 주변 용품을 치워요.');
insert into kb.step_source_links(procedure_version_id, step_no, source_version_id, section_locator, support_note) values ('aa1d9588-4442-5df5-bdc5-c63e4e8a5c9e'::uuid, 1, 'd153c12d-48a4-5322-aa9e-fae37414889b'::uuid, 'verified-scope:me_indoor_air', '검수자가 단계 문안과 출처의 적용 범위를 대조함');
insert into kb.step_source_links(procedure_version_id, step_no, source_version_id, section_locator, support_note) values ('aa1d9588-4442-5df5-bdc5-c63e4e8a5c9e'::uuid, 1, 'e25aadb2-c343-5775-81f2-3dec47720952'::uuid, 'verified-scope:lh_home_ventilation', '검수자가 단계 문안과 출처의 적용 범위를 대조함');
insert into kb.procedure_steps(id, procedure_version_id, step_no, stage_code, instruction, detail, completion_cue, caution, speech_text) values ('4c96444d-5792-50ef-9a78-9c09bd871c93'::uuid, 'aa1d9588-4442-5df5-bdc5-c63e4e8a5c9e'::uuid, 2, 'protect', '장갑과 부드러운 천·솔을 준비해요.', '표면을 긁을 수 있는 금속·거친 수세미는 치우고 물기를 닦을 마른 천을 따로 둬요.', '장갑과 비연마 도구가 준비됐어요.', null, '장갑과 부드러운 천·솔을 준비해요. 표면을 긁을 수 있는 금속·거친 수세미는 치우고 물기를 닦을 마른 천을 따로 둬요.');
insert into kb.step_source_links(procedure_version_id, step_no, source_version_id, section_locator, support_note) values ('aa1d9588-4442-5df5-bdc5-c63e4e8a5c9e'::uuid, 2, '213afb63-6240-58be-9627-a9d2db71ad8a'::uuid, 'verified-scope:aci_hard_surfaces', '검수자가 단계 문안과 출처의 적용 범위를 대조함');
insert into kb.procedure_steps(id, procedure_version_id, step_no, stage_code, instruction, detail, completion_cue, caution, speech_text) values ('768fa384-e87f-5827-ba53-417c82cc7436'::uuid, 'aa1d9588-4442-5df5-bdc5-c63e4e8a5c9e'::uuid, 3, 'act', '미지근한 물로 뿌연 흔적을 먼저 불려요.', '물기를 짠 부드러운 천을 흔적 위에 올리거나 표면을 가볍게 적셔 마른 비누막을 부드럽게 해요.', '흔적이 젖고 주변으로 물이 흐르지 않아요.', null, '미지근한 물로 뿌연 흔적을 먼저 불려요. 물기를 짠 부드러운 천을 흔적 위에 올리거나 표면을 가볍게 적셔 마른 비누막을 부드럽게 해요.');
insert into kb.step_source_links(procedure_version_id, step_no, source_version_id, section_locator, support_note) values ('aa1d9588-4442-5df5-bdc5-c63e4e8a5c9e'::uuid, 3, 'fe74460b-c981-53e9-9c4b-0f06aa60b56a'::uuid, 'verified-scope:cdc_home_cleaning', '검수자가 단계 문안과 출처의 적용 범위를 대조함');
insert into kb.step_source_links(procedure_version_id, step_no, source_version_id, section_locator, support_note) values ('aa1d9588-4442-5df5-bdc5-c63e4e8a5c9e'::uuid, 3, '213afb63-6240-58be-9627-a9d2db71ad8a'::uuid, 'verified-scope:aci_hard_surfaces', '검수자가 단계 문안과 출처의 적용 범위를 대조함');
insert into kb.procedure_steps(id, procedure_version_id, step_no, stage_code, instruction, detail, completion_cue, caution, speech_text) values ('3371b22e-a314-5a65-a951-2c38374484f6'::uuid, 'aa1d9588-4442-5df5-bdc5-c63e4e8a5c9e'::uuid, 4, 'act', '미지근한 물로 작은 면씩 부드럽게 닦아요.', '물에 적신 천이나 부드러운 솔로 뿌연 막을 짧게 여러 번 닦고, 닦인 잔여물이 퍼지면 도구를 깨끗이 헹궈요.', '선택한 면의 느슨한 비누막이 닦였어요.', '표면 변화가 보이면 멈춰요.', '미지근한 물로 작은 면씩 부드럽게 닦아요. 물에 적신 천이나 부드러운 솔로 뿌연 막을 짧게 여러 번 닦고, 닦인 잔여물이 퍼지면 도구를 깨끗이 헹궈요.');
insert into kb.step_source_links(procedure_version_id, step_no, source_version_id, section_locator, support_note) values ('aa1d9588-4442-5df5-bdc5-c63e4e8a5c9e'::uuid, 4, 'fe74460b-c981-53e9-9c4b-0f06aa60b56a'::uuid, 'verified-scope:cdc_home_cleaning', '검수자가 단계 문안과 출처의 적용 범위를 대조함');
insert into kb.step_source_links(procedure_version_id, step_no, source_version_id, section_locator, support_note) values ('aa1d9588-4442-5df5-bdc5-c63e4e8a5c9e'::uuid, 4, '213afb63-6240-58be-9627-a9d2db71ad8a'::uuid, 'verified-scope:aci_hard_surfaces', '검수자가 단계 문안과 출처의 적용 범위를 대조함');
insert into kb.procedure_steps(id, procedure_version_id, step_no, stage_code, instruction, detail, completion_cue, caution, speech_text) values ('623c6914-e28f-51ba-801e-da900275d0d3'::uuid, 'aa1d9588-4442-5df5-bdc5-c63e4e8a5c9e'::uuid, 5, 'rinse', '깨끗한 물로 잔여물을 충분히 헹궈요.', '위에서 아래로 헹구며 모서리와 틈에 닦인 잔여물이 남지 않았는지 확인해요.', '닦인 잔여물이 보이지 않아요.', null, '깨끗한 물로 잔여물을 충분히 헹궈요. 위에서 아래로 헹구며 모서리와 틈에 닦인 잔여물이 남지 않았는지 확인해요.');
insert into kb.step_source_links(procedure_version_id, step_no, source_version_id, section_locator, support_note) values ('aa1d9588-4442-5df5-bdc5-c63e4e8a5c9e'::uuid, 5, '213afb63-6240-58be-9627-a9d2db71ad8a'::uuid, 'verified-scope:aci_hard_surfaces', '검수자가 단계 문안과 출처의 적용 범위를 대조함');
insert into kb.procedure_steps(id, procedure_version_id, step_no, stage_code, instruction, detail, completion_cue, caution, speech_text) values ('358747a8-a918-5c79-a114-8c242fff0465'::uuid, 'aa1d9588-4442-5df5-bdc5-c63e4e8a5c9e'::uuid, 6, 'dry', '물기를 제거하고 표면을 완전히 말려요.', '스퀴지나 마른 천으로 물기를 닦고 샤워문이나 커튼을 열어 공기가 통하게 둬요.', '고인 물이 없고 표면이 마르고 있어요.', null, '물기를 제거하고 표면을 완전히 말려요. 스퀴지나 마른 천으로 물기를 닦고 샤워문이나 커튼을 열어 공기가 통하게 둬요.');
insert into kb.step_source_links(procedure_version_id, step_no, source_version_id, section_locator, support_note) values ('aa1d9588-4442-5df5-bdc5-c63e4e8a5c9e'::uuid, 6, '789fb545-60ce-51e2-b513-d0a782645106'::uuid, 'verified-scope:aci_home_routine', '검수자가 단계 문안과 출처의 적용 범위를 대조함');
insert into kb.review_events(id, entity_type, entity_version_id, decision, reason, reviewer_ref, created_at) values ('d079fcf5-3ad8-51ff-aea9-0c167be0be0c'::uuid, 'procedure_version', 'aa1d9588-4442-5df5-bdc5-c63e4e8a5c9e'::uuid, 'approved', '단계 순서·출처 범위·안전 문구·실행 가능성 검수 완료', 'knowledge-editor-2026-08-25', '2026-08-25T06:00:00Z'::timestamptz);
insert into kb.procedures(id, procedure_key) values ('127cea9e-768e-52db-b5b9-f5e6d4bc6929'::uuid, 'bathroom-mold-v1');
insert into kb.procedure_versions(id, procedure_id, revision, status, locale, title, summary, required_step_count, content_hash) values ('e4f59381-1071-5c3d-aaee-5cbdc90e73a9'::uuid, '127cea9e-768e-52db-b5b9-f5e6d4bc6929'::uuid, 1, 'draft', 'ko-KR', '욕실 곰팡이 추정 흔적 청소', '사용자가 작은 범위의 곰팡이 추정 흔적을 확인한 경우, 환기·보호구·작은 범위 작업·헹굼·완전 건조를 지키며 6단계로 진행해요.', 6, '75c3e2d71b1bb6b29c55c0f5026fc236d57920d3a7e54e57f702a9ba14cea827');
insert into kb.procedure_steps(id, procedure_version_id, step_no, stage_code, instruction, detail, completion_cue, caution, speech_text) values ('94cef293-0fdb-52a9-95aa-db92726fee3e'::uuid, 'e4f59381-1071-5c3d-aaee-5cbdc90e73a9'::uuid, 1, 'prepare', '문과 창을 열고 환풍기를 켜요.', '신선한 공기가 들어오고 욕실 공기가 밖으로 빠져나가게 환기한 뒤 작업 구역을 작게 정해요.', '문이나 창이 열리고 환풍기가 작동해요.', '환기가 되지 않거나 자극이 느껴지면 작업을 시작하지 않아요.', '문과 창을 열고 환풍기를 켜요. 신선한 공기가 들어오고 욕실 공기가 밖으로 빠져나가게 환기한 뒤 작업 구역을 작게 정해요.');
insert into kb.step_source_links(procedure_version_id, step_no, source_version_id, section_locator, support_note) values ('e4f59381-1071-5c3d-aaee-5cbdc90e73a9'::uuid, 1, '2a1a39a1-21c1-50c0-8d16-765b30370cbf'::uuid, 'verified-scope:cdc_mold_cleanup', '검수자가 단계 문안과 출처의 적용 범위를 대조함');
insert into kb.step_source_links(procedure_version_id, step_no, source_version_id, section_locator, support_note) values ('e4f59381-1071-5c3d-aaee-5cbdc90e73a9'::uuid, 1, 'e25aadb2-c343-5775-81f2-3dec47720952'::uuid, 'verified-scope:lh_home_ventilation', '검수자가 단계 문안과 출처의 적용 범위를 대조함');
insert into kb.procedure_steps(id, procedure_version_id, step_no, stage_code, instruction, detail, completion_cue, caution, speech_text) values ('d34463c4-5546-53de-8b11-082244fe43fb'::uuid, 'e4f59381-1071-5c3d-aaee-5cbdc90e73a9'::uuid, 2, 'protect', '장갑과 눈 보호구를 착용하고 주변 물건을 치워요.', '피부와 눈을 보호하고, 수건과 욕실 용품을 작업 구역 밖으로 옮겨 작은 흔적만 보이게 해요.', '장갑과 눈 보호구를 착용했고 작은 작업 구역이 비었어요.', '보호구가 없으면 직접 닦기보다 전문 도움을 선택해요.', '장갑과 눈 보호구를 착용하고 주변 물건을 치워요. 피부와 눈을 보호하고, 수건과 욕실 용품을 작업 구역 밖으로 옮겨 작은 흔적만 보이게 해요.');
insert into kb.step_source_links(procedure_version_id, step_no, source_version_id, section_locator, support_note) values ('e4f59381-1071-5c3d-aaee-5cbdc90e73a9'::uuid, 2, '2a1a39a1-21c1-50c0-8d16-765b30370cbf'::uuid, 'verified-scope:cdc_mold_cleanup', '검수자가 단계 문안과 출처의 적용 범위를 대조함');
insert into kb.procedure_steps(id, procedure_version_id, step_no, stage_code, instruction, detail, completion_cue, caution, speech_text) values ('e8595623-9397-5916-ac8f-8fcebd642bfd'::uuid, 'e4f59381-1071-5c3d-aaee-5cbdc90e73a9'::uuid, 3, 'preclean', '미지근한 물에 적신 부드러운 천을 작은 흔적 위에 올려요.', '천의 물기를 짠 뒤 사용자가 확인한 작은 단단한 표면만 덮고 주변으로 물이 흐르지 않게 해요.', '젖은 천이 확인한 작은 흔적만 덮고 있어요.', '흡수성 재료나 벽 안쪽으로 번진 흔적은 직접 닦지 않아요.', '미지근한 물에 적신 부드러운 천을 작은 흔적 위에 올려요. 천의 물기를 짠 뒤 사용자가 확인한 작은 단단한 표면만 덮고 주변으로 물이 흐르지 않게 해요.');
insert into kb.step_source_links(procedure_version_id, step_no, source_version_id, section_locator, support_note) values ('e4f59381-1071-5c3d-aaee-5cbdc90e73a9'::uuid, 3, '2a1a39a1-21c1-50c0-8d16-765b30370cbf'::uuid, 'verified-scope:cdc_mold_cleanup', '검수자가 단계 문안과 출처의 적용 범위를 대조함');
insert into kb.step_source_links(procedure_version_id, step_no, source_version_id, section_locator, support_note) values ('e4f59381-1071-5c3d-aaee-5cbdc90e73a9'::uuid, 3, 'f0f1a866-d5d2-50b8-92a8-257db1074c8f'::uuid, 'verified-scope:epa_mold_home', '검수자가 단계 문안과 출처의 적용 범위를 대조함');
insert into kb.procedure_steps(id, procedure_version_id, step_no, stage_code, instruction, detail, completion_cue, caution, speech_text) values ('ee624480-4217-5a3e-92d6-0a69dd38f75a'::uuid, 'e4f59381-1071-5c3d-aaee-5cbdc90e73a9'::uuid, 4, 'act', '부드러운 천으로 작은 구역씩 닦아요.', '강하게 문지르지 말고 천의 깨끗한 면을 바꿔가며 물로 헹굴 수 있는 단단한 표면만 닦아요.', '선택한 작은 구역의 느슨한 흔적이 천에 묻어났어요.', '자극이 느껴지거나 흔적이 넓게 이어지면 바로 중단해요.', '부드러운 천으로 작은 구역씩 닦아요. 강하게 문지르지 말고 천의 깨끗한 면을 바꿔가며 물로 헹굴 수 있는 단단한 표면만 닦아요.');
insert into kb.step_source_links(procedure_version_id, step_no, source_version_id, section_locator, support_note) values ('e4f59381-1071-5c3d-aaee-5cbdc90e73a9'::uuid, 4, 'f0f1a866-d5d2-50b8-92a8-257db1074c8f'::uuid, 'verified-scope:epa_mold_home', '검수자가 단계 문안과 출처의 적용 범위를 대조함');
insert into kb.step_source_links(procedure_version_id, step_no, source_version_id, section_locator, support_note) values ('e4f59381-1071-5c3d-aaee-5cbdc90e73a9'::uuid, 4, '2a1a39a1-21c1-50c0-8d16-765b30370cbf'::uuid, 'verified-scope:cdc_mold_cleanup', '검수자가 단계 문안과 출처의 적용 범위를 대조함');
insert into kb.procedure_steps(id, procedure_version_id, step_no, stage_code, instruction, detail, completion_cue, caution, speech_text) values ('2b3b1d64-0c01-5ede-8c13-2299c5d1cfac'::uuid, 'e4f59381-1071-5c3d-aaee-5cbdc90e73a9'::uuid, 5, 'rinse', '깨끗한 물로 닦은 구역을 충분히 헹궈요.', '새 천에 깨끗한 물을 묻혀 닦거나, 물로 헹굴 수 있는 표면은 위에서 아래로 가볍게 헹궈 닦인 잔여물을 제거해요.', '닦인 잔여물이 보이지 않아요.', '다른 방법을 추가하지 않아요.', '깨끗한 물로 닦은 구역을 충분히 헹궈요. 새 천에 깨끗한 물을 묻혀 닦거나, 물로 헹굴 수 있는 표면은 위에서 아래로 가볍게 헹궈 닦인 잔여물을 제거해요.');
insert into kb.step_source_links(procedure_version_id, step_no, source_version_id, section_locator, support_note) values ('e4f59381-1071-5c3d-aaee-5cbdc90e73a9'::uuid, 5, 'f0f1a866-d5d2-50b8-92a8-257db1074c8f'::uuid, 'verified-scope:epa_mold_home', '검수자가 단계 문안과 출처의 적용 범위를 대조함');
insert into kb.step_source_links(procedure_version_id, step_no, source_version_id, section_locator, support_note) values ('e4f59381-1071-5c3d-aaee-5cbdc90e73a9'::uuid, 5, '213afb63-6240-58be-9627-a9d2db71ad8a'::uuid, 'verified-scope:aci_hard_surfaces', '검수자가 단계 문안과 출처의 적용 범위를 대조함');
insert into kb.procedure_steps(id, procedure_version_id, step_no, stage_code, instruction, detail, completion_cue, caution, speech_text) values ('c1a73a25-802a-5290-9f1e-ea8b62836382'::uuid, 'e4f59381-1071-5c3d-aaee-5cbdc90e73a9'::uuid, 6, 'dry', '물기를 제거하고 완전히 건조해요.', '마른 천이나 스퀴지로 물기를 제거하고 환기를 계속해요. 흔적이 넓거나 반복되거나 흡수성 재료로 번졌다면 직접 작업을 멈추고 전문 도움을 받아요.', '고인 물이 없고 작업 구역이 마르고 있어요.', '누수나 반복 원인이 남아 있으면 청소만 반복하지 않아요.', '물기를 제거하고 완전히 건조해요. 마른 천이나 스퀴지로 물기를 제거하고 환기를 계속해요. 흔적이 넓거나 반복되거나 흡수성 재료로 번졌다면 직접 작업을 멈추고 전문 도움을 받아요.');
insert into kb.step_source_links(procedure_version_id, step_no, source_version_id, section_locator, support_note) values ('e4f59381-1071-5c3d-aaee-5cbdc90e73a9'::uuid, 6, 'f0f1a866-d5d2-50b8-92a8-257db1074c8f'::uuid, 'verified-scope:epa_mold_home', '검수자가 단계 문안과 출처의 적용 범위를 대조함');
