insert into kb.procedures(id, procedure_key) values ('357bd426-fc48-5ff4-823c-2e349f194f1b'::uuid, 'kitchen-grease-v1');
insert into kb.procedure_versions(id, procedure_id, revision, status, locale, title, summary, required_step_count, content_hash) values ('17a1d7fb-e01a-5166-84df-c5f4c36c9c51'::uuid, '357bd426-fc48-5ff4-823c-2e349f194f1b'::uuid, 1, 'draft', 'ko-KR', '주방 조리 상판의 기름때 추정 흔적 청소', '전원을 끄고 열을 식힌 뒤 큰 부스러기를 제거하고, 공식 관리 안내 범위에서 작은 면씩 닦아 완전히 말려요.', 6, 'a4a1abf9a10b438581cff1e5c68702b2e77ca50e976d4ce7305642e24ccc9b24');
insert into kb.procedure_steps(id, procedure_version_id, step_no, stage_code, instruction, detail, completion_cue, caution, speech_text) values ('7aa6c271-960b-57a4-98b2-e9b65d4544e1'::uuid, '17a1d7fb-e01a-5166-84df-c5f4c36c9c51'::uuid, 1, 'prepare', '조리기구 전원을 끄고 열이 완전히 식을 때까지 기다려요.', '불꽃과 전원이 꺼졌는지 확인하고 손을 가까이 대도 열기가 느껴지지 않을 때만 청소를 시작해요.', '전원이 꺼지고 상판과 부품의 열이 식었어요.', '뜨거운 상판을 젖은 천으로 닦지 않아요.', '조리기구 전원을 끄고 열이 완전히 식을 때까지 기다려요. 불꽃과 전원이 꺼졌는지 확인하고 손을 가까이 대도 열기가 느껴지지 않을 때만 청소를 시작해요.');
insert into kb.step_source_links(procedure_version_id, step_no, source_version_id, section_locator, support_note) values ('17a1d7fb-e01a-5166-84df-c5f4c36c9c51'::uuid, 1, '60c12c9f-5762-5c3a-a781-f8f3dc746fb0'::uuid, 'verified-scope:lg_gas_range', '검수자가 단계 문안과 출처의 적용 범위를 대조함');
insert into kb.step_source_links(procedure_version_id, step_no, source_version_id, section_locator, support_note) values ('17a1d7fb-e01a-5166-84df-c5f4c36c9c51'::uuid, 1, '9fead9b4-ff66-5daa-bac8-9dc75aea4484'::uuid, 'verified-scope:lg_induction', '검수자가 단계 문안과 출처의 적용 범위를 대조함');
insert into kb.procedure_steps(id, procedure_version_id, step_no, stage_code, instruction, detail, completion_cue, caution, speech_text) values ('4a51aa7a-4caa-5da8-b95a-b0dfd428a7de'::uuid, '17a1d7fb-e01a-5166-84df-c5f4c36c9c51'::uuid, 2, 'protect', '제품의 공식 관리 안내와 장갑을 확인해요.', '모델 설명서에서 분리 가능한 부품과 허용된 도구를 확인하고, 확인되지 않은 부품은 억지로 빼지 않아요.', '청소 가능한 범위와 사용할 부드러운 도구가 정해졌어요.', '사진만 보고 상판 재질이나 도구 적합성을 판단하지 않아요.', '제품의 공식 관리 안내와 장갑을 확인해요. 모델 설명서에서 분리 가능한 부품과 허용된 도구를 확인하고, 확인되지 않은 부품은 억지로 빼지 않아요.');
insert into kb.step_source_links(procedure_version_id, step_no, source_version_id, section_locator, support_note) values ('17a1d7fb-e01a-5166-84df-c5f4c36c9c51'::uuid, 2, 'fe74460b-c981-53e9-9c4b-0f06aa60b56a'::uuid, 'verified-scope:cdc_home_cleaning', '검수자가 단계 문안과 출처의 적용 범위를 대조함');
insert into kb.step_source_links(procedure_version_id, step_no, source_version_id, section_locator, support_note) values ('17a1d7fb-e01a-5166-84df-c5f4c36c9c51'::uuid, 2, '60c12c9f-5762-5c3a-a781-f8f3dc746fb0'::uuid, 'verified-scope:lg_gas_range', '검수자가 단계 문안과 출처의 적용 범위를 대조함');
insert into kb.step_source_links(procedure_version_id, step_no, source_version_id, section_locator, support_note) values ('17a1d7fb-e01a-5166-84df-c5f4c36c9c51'::uuid, 2, '9fead9b4-ff66-5daa-bac8-9dc75aea4484'::uuid, 'verified-scope:lg_induction', '검수자가 단계 문안과 출처의 적용 범위를 대조함');
insert into kb.procedure_steps(id, procedure_version_id, step_no, stage_code, instruction, detail, completion_cue, caution, speech_text) values ('8f8b1b7d-34ca-5951-9ae3-8dc88a538dca'::uuid, '17a1d7fb-e01a-5166-84df-c5f4c36c9c51'::uuid, 3, 'preclean', '굳지 않은 음식물과 큰 부스러기를 먼저 걷어요.', '마른 천이나 부드러운 도구로 상판의 큰 조각을 모아 버리고 조작부 틈으로 밀어 넣지 않아요.', '상판에 큰 부스러기가 남지 않았어요.', null, '굳지 않은 음식물과 큰 부스러기를 먼저 걷어요. 마른 천이나 부드러운 도구로 상판의 큰 조각을 모아 버리고 조작부 틈으로 밀어 넣지 않아요.');
insert into kb.step_source_links(procedure_version_id, step_no, source_version_id, section_locator, support_note) values ('17a1d7fb-e01a-5166-84df-c5f4c36c9c51'::uuid, 3, '789fb545-60ce-51e2-b513-d0a782645106'::uuid, 'verified-scope:aci_home_routine', '검수자가 단계 문안과 출처의 적용 범위를 대조함');
insert into kb.step_source_links(procedure_version_id, step_no, source_version_id, section_locator, support_note) values ('17a1d7fb-e01a-5166-84df-c5f4c36c9c51'::uuid, 3, '9fead9b4-ff66-5daa-bac8-9dc75aea4484'::uuid, 'verified-scope:lg_induction', '검수자가 단계 문안과 출처의 적용 범위를 대조함');
insert into kb.procedure_steps(id, procedure_version_id, step_no, stage_code, instruction, detail, completion_cue, caution, speech_text) values ('c1b96ac3-b34f-5903-a261-2796175ff566'::uuid, '17a1d7fb-e01a-5166-84df-c5f4c36c9c51'::uuid, 4, 'act', '공식 관리 안내 범위에서 작은 면씩 닦아요.', '물기를 꼭 짠 부드러운 천부터 사용하고, 기름이 묻으면 천의 깨끗한 면으로 바꿔 한 방향씩 닦아요.', '선택한 작은 면의 느슨한 기름막이 닦였어요.', '연마성이 강한 도구와 확인되지 않은 제품을 추가하지 않아요.', '공식 관리 안내 범위에서 작은 면씩 닦아요. 물기를 꼭 짠 부드러운 천부터 사용하고, 기름이 묻으면 천의 깨끗한 면으로 바꿔 한 방향씩 닦아요.');
insert into kb.step_source_links(procedure_version_id, step_no, source_version_id, section_locator, support_note) values ('17a1d7fb-e01a-5166-84df-c5f4c36c9c51'::uuid, 4, 'fe74460b-c981-53e9-9c4b-0f06aa60b56a'::uuid, 'verified-scope:cdc_home_cleaning', '검수자가 단계 문안과 출처의 적용 범위를 대조함');
insert into kb.step_source_links(procedure_version_id, step_no, source_version_id, section_locator, support_note) values ('17a1d7fb-e01a-5166-84df-c5f4c36c9c51'::uuid, 4, '9fead9b4-ff66-5daa-bac8-9dc75aea4484'::uuid, 'verified-scope:lg_induction', '검수자가 단계 문안과 출처의 적용 범위를 대조함');
insert into kb.procedure_steps(id, procedure_version_id, step_no, stage_code, instruction, detail, completion_cue, caution, speech_text) values ('44591c88-2fab-53c9-9016-51c51b66125d'::uuid, '17a1d7fb-e01a-5166-84df-c5f4c36c9c51'::uuid, 5, 'rinse', '깨끗한 물을 묻힌 천으로 닦은 면을 마무리해요.', '식품이 닿는 주변은 깨끗한 물을 묻혀 꼭 짠 새 천으로 보이는 잔여물이 없게 닦아요.', '닦인 잔여물이 보이지 않아요.', '액체가 조작부나 틈으로 흐르지 않게 해요.', '깨끗한 물을 묻힌 천으로 닦은 면을 마무리해요. 식품이 닿는 주변은 깨끗한 물을 묻혀 꼭 짠 새 천으로 보이는 잔여물이 없게 닦아요.');
insert into kb.step_source_links(procedure_version_id, step_no, source_version_id, section_locator, support_note) values ('17a1d7fb-e01a-5166-84df-c5f4c36c9c51'::uuid, 5, 'fe74460b-c981-53e9-9c4b-0f06aa60b56a'::uuid, 'verified-scope:cdc_home_cleaning', '검수자가 단계 문안과 출처의 적용 범위를 대조함');
insert into kb.procedure_steps(id, procedure_version_id, step_no, stage_code, instruction, detail, completion_cue, caution, speech_text) values ('1faba219-aaa4-54d9-ada5-7a38c2c769bb'::uuid, '17a1d7fb-e01a-5166-84df-c5f4c36c9c51'::uuid, 6, 'dry', '마른 천으로 물기를 닦고 부품을 완전히 말려요.', '상판과 분리해 씻은 공식 세척 가능 부품을 완전히 건조한 뒤 원래 위치에 조립해요.', '상판과 부품이 마르고 원래 위치에 있어요.', null, '마른 천으로 물기를 닦고 부품을 완전히 말려요. 상판과 분리해 씻은 공식 세척 가능 부품을 완전히 건조한 뒤 원래 위치에 조립해요.');
