insert into kb.procedures(id, procedure_key) values ('faeea881-fd1c-5812-b424-10d91ca1ffa2'::uuid, 'generic-surface-clean-v1');
insert into kb.procedure_versions(id, procedure_id, revision, status, locale, title, summary, required_step_count, content_hash) values ('df37b9d3-1bf0-5f20-8257-4e89b77289ce'::uuid, 'faeea881-fd1c-5812-b424-10d91ca1ffa2'::uuid, 1, 'draft', 'ko-KR', '확인한 일반 표면 청소', '큰 먼지를 먼저 제거하고 관리 안내가 확인된 범위에서 작은 면부터 닦아 건조해요.', 5, 'e6c73cc0e539414264d48bdd61ed5145e3e16883aaced339051d04b41ed951a6');
insert into kb.procedure_steps(id, procedure_version_id, step_no, stage_code, instruction, detail, completion_cue, caution, speech_text) values ('c4435aad-5d98-5cbc-8923-76b190e9da12'::uuid, 'df37b9d3-1bf0-5f20-8257-4e89b77289ce'::uuid, 1, 'prepare', '청소할 작은 구역과 부드러운 도구를 정해요.', '표면 한 면만 선택하고 마른 천, 물기를 꼭 짤 천과 쓰레기봉투를 준비해요.', '작업 구역과 도구가 정해졌어요.', null, '청소할 작은 구역과 부드러운 도구를 정해요. 표면 한 면만 선택하고 마른 천, 물기를 꼭 짤 천과 쓰레기봉투를 준비해요.');
insert into kb.step_source_links(procedure_version_id, step_no, source_version_id, section_locator, support_note) values ('df37b9d3-1bf0-5f20-8257-4e89b77289ce'::uuid, 1, '789fb545-60ce-51e2-b513-d0a782645106'::uuid, 'verified-scope:aci_home_routine', '검수자가 단계 문안과 출처의 적용 범위를 대조함');
insert into kb.procedure_steps(id, procedure_version_id, step_no, stage_code, instruction, detail, completion_cue, caution, speech_text) values ('a9a4d94f-2822-54cc-95bd-0b06aebbb67a'::uuid, 'df37b9d3-1bf0-5f20-8257-4e89b77289ce'::uuid, 2, 'protect', '표면과 주변 물건의 관리 안내를 확인해요.', '전자기기·도장·코팅처럼 물 사용이 불확실하면 마른 청소만 진행해요.', '물 사용 가능 여부를 확인했거나 마른 방식으로 정했어요.', '재질을 사진만 보고 추정하지 않아요.', '표면과 주변 물건의 관리 안내를 확인해요. 전자기기·도장·코팅처럼 물 사용이 불확실하면 마른 청소만 진행해요.');
insert into kb.step_source_links(procedure_version_id, step_no, source_version_id, section_locator, support_note) values ('df37b9d3-1bf0-5f20-8257-4e89b77289ce'::uuid, 2, 'fe74460b-c981-53e9-9c4b-0f06aa60b56a'::uuid, 'verified-scope:cdc_home_cleaning', '검수자가 단계 문안과 출처의 적용 범위를 대조함');
insert into kb.procedure_steps(id, procedure_version_id, step_no, stage_code, instruction, detail, completion_cue, caution, speech_text) values ('b6dca57c-d6d7-5deb-bd9f-625c6c10e100'::uuid, 'df37b9d3-1bf0-5f20-8257-4e89b77289ce'::uuid, 3, 'preclean', '큰 물건과 마른 먼지를 먼저 치워요.', '큰 부스러기는 봉투에 버리고 느슨한 먼지는 마른 천으로 한곳에 모아요.', '닦을 면에 큰 물건과 느슨한 먼지가 없어요.', null, '큰 물건과 마른 먼지를 먼저 치워요. 큰 부스러기는 봉투에 버리고 느슨한 먼지는 마른 천으로 한곳에 모아요.');
insert into kb.step_source_links(procedure_version_id, step_no, source_version_id, section_locator, support_note) values ('df37b9d3-1bf0-5f20-8257-4e89b77289ce'::uuid, 3, 'd153c12d-48a4-5322-aa9e-fae37414889b'::uuid, 'verified-scope:me_indoor_air', '검수자가 단계 문안과 출처의 적용 범위를 대조함');
insert into kb.step_source_links(procedure_version_id, step_no, source_version_id, section_locator, support_note) values ('df37b9d3-1bf0-5f20-8257-4e89b77289ce'::uuid, 3, '789fb545-60ce-51e2-b513-d0a782645106'::uuid, 'verified-scope:aci_home_routine', '검수자가 단계 문안과 출처의 적용 범위를 대조함');
insert into kb.procedure_steps(id, procedure_version_id, step_no, stage_code, instruction, detail, completion_cue, caution, speech_text) values ('f31beb9a-d881-530a-a3b4-60a3749847bf'::uuid, 'df37b9d3-1bf0-5f20-8257-4e89b77289ce'::uuid, 4, 'act', '허용된 범위에서 작은 곳부터 부드럽게 닦아요.', '물 사용이 가능한 경우에만 물기를 꼭 짠 천으로 눈에 띄지 않는 곳부터 한 방향씩 닦아요.', '작은 시험 구역에 표면 변화가 없고 보이는 자국이 닦였어요.', '색 변화나 벗겨짐이 보이면 멈춰요.', '허용된 범위에서 작은 곳부터 부드럽게 닦아요. 물 사용이 가능한 경우에만 물기를 꼭 짠 천으로 눈에 띄지 않는 곳부터 한 방향씩 닦아요.');
insert into kb.step_source_links(procedure_version_id, step_no, source_version_id, section_locator, support_note) values ('df37b9d3-1bf0-5f20-8257-4e89b77289ce'::uuid, 4, 'fe74460b-c981-53e9-9c4b-0f06aa60b56a'::uuid, 'verified-scope:cdc_home_cleaning', '검수자가 단계 문안과 출처의 적용 범위를 대조함');
insert into kb.step_source_links(procedure_version_id, step_no, source_version_id, section_locator, support_note) values ('df37b9d3-1bf0-5f20-8257-4e89b77289ce'::uuid, 4, '213afb63-6240-58be-9627-a9d2db71ad8a'::uuid, 'verified-scope:aci_hard_surfaces', '검수자가 단계 문안과 출처의 적용 범위를 대조함');
insert into kb.procedure_steps(id, procedure_version_id, step_no, stage_code, instruction, detail, completion_cue, caution, speech_text) values ('9d7f9702-53c1-5def-85b8-7ffdb90019a5'::uuid, 'df37b9d3-1bf0-5f20-8257-4e89b77289ce'::uuid, 5, 'dry', '물기와 남은 부스러기를 제거해요.', '마른 천으로 가장자리까지 닦고 사용한 도구와 옮긴 물건을 정리해요.', '표면이 마르고 작업 구역이 정리됐어요.', null, '물기와 남은 부스러기를 제거해요. 마른 천으로 가장자리까지 닦고 사용한 도구와 옮긴 물건을 정리해요.');
insert into kb.step_source_links(procedure_version_id, step_no, source_version_id, section_locator, support_note) values ('df37b9d3-1bf0-5f20-8257-4e89b77289ce'::uuid, 5, '213afb63-6240-58be-9627-a9d2db71ad8a'::uuid, 'verified-scope:aci_hard_surfaces', '검수자가 단계 문안과 출처의 적용 범위를 대조함');
insert into kb.step_source_links(procedure_version_id, step_no, source_version_id, section_locator, support_note) values ('df37b9d3-1bf0-5f20-8257-4e89b77289ce'::uuid, 5, '789fb545-60ce-51e2-b513-d0a782645106'::uuid, 'verified-scope:aci_home_routine', '검수자가 단계 문안과 출처의 적용 범위를 대조함');
