insert into kb.procedure_versions(id, procedure_id, revision, status, locale, title, summary, required_step_count, content_hash) values ('4035f341-c148-547a-8716-bf1b2b7188d1'::uuid, '533f208c-063c-5d81-96ff-2086d6c1bb4c'::uuid, 1, 'draft', 'ko-KR', '한 구역 물건 정리', '통로를 지키며 남길 것·옮길 것·내보낼 것을 나누고 지금 쓰는 물건부터 제자리에 둬요.', 5, '7c3408d096ceee15338b118596705d2340648f6ad4e9052e834da2398fd3cdfa');
insert into kb.procedure_steps(id, procedure_version_id, step_no, stage_code, instruction, detail, completion_cue, caution, speech_text) values ('2e6eec10-7baf-5fd3-832e-35c8ffe554ef'::uuid, '4035f341-c148-547a-8716-bf1b2b7188d1'::uuid, 1, 'prepare', '바구니 세 개와 한 구역을 정해요.', '남길 것, 다른 곳으로 옮길 것, 버리거나 재활용할 것을 담을 자리를 만들어요.', '세 분류 자리와 작업할 한 구역이 정해졌어요.', '통로와 출입문 앞은 비워 둬요.', '바구니 세 개와 한 구역을 정해요. 남길 것, 다른 곳으로 옮길 것, 버리거나 재활용할 것을 담을 자리를 만들어요.');
insert into kb.step_source_links(procedure_version_id, step_no, source_version_id, section_locator, support_note) values ('4035f341-c148-547a-8716-bf1b2b7188d1'::uuid, 1, '789fb545-60ce-51e2-b513-d0a782645106'::uuid, 'verified-scope:aci_home_routine', '검수자가 단계 문안과 출처의 적용 범위를 대조함');
insert into kb.procedure_steps(id, procedure_version_id, step_no, stage_code, instruction, detail, completion_cue, caution, speech_text) values ('56653e6b-a420-51cc-97e7-01f555c988c3'::uuid, '4035f341-c148-547a-8716-bf1b2b7188d1'::uuid, 2, 'act', '눈앞의 물건을 세 갈래로 하나씩 나눠요.', '결정을 오래 고민하지 말고 망설여지는 물건은 남길 것 바구니 한쪽에 임시로 둬요.', '선택한 구역의 물건이 세 분류 안에 들어갔어요.', null, '눈앞의 물건을 세 갈래로 하나씩 나눠요. 결정을 오래 고민하지 말고 망설여지는 물건은 남길 것 바구니 한쪽에 임시로 둬요.');
insert into kb.step_source_links(procedure_version_id, step_no, source_version_id, section_locator, support_note) values ('4035f341-c148-547a-8716-bf1b2b7188d1'::uuid, 2, '789fb545-60ce-51e2-b513-d0a782645106'::uuid, 'verified-scope:aci_home_routine', '검수자가 단계 문안과 출처의 적용 범위를 대조함');
insert into kb.procedure_steps(id, procedure_version_id, step_no, stage_code, instruction, detail, completion_cue, caution, speech_text) values ('d1746d7a-de25-552c-9be2-b9fb48aca6f4'::uuid, '4035f341-c148-547a-8716-bf1b2b7188d1'::uuid, 3, 'act', '오늘 쓰는 물건부터 손 닿는 자리에 둬요.', '자주 쓰는 것만 가까운 곳에 두고 나머지는 이름이 맞는 수납 위치로 옮겨요.', '지금 쓰는 물건이 한눈에 보여요.', null, '오늘 쓰는 물건부터 손 닿는 자리에 둬요. 자주 쓰는 것만 가까운 곳에 두고 나머지는 이름이 맞는 수납 위치로 옮겨요.');
insert into kb.step_source_links(procedure_version_id, step_no, source_version_id, section_locator, support_note) values ('4035f341-c148-547a-8716-bf1b2b7188d1'::uuid, 3, '789fb545-60ce-51e2-b513-d0a782645106'::uuid, 'verified-scope:aci_home_routine', '검수자가 단계 문안과 출처의 적용 범위를 대조함');
insert into kb.procedure_steps(id, procedure_version_id, step_no, stage_code, instruction, detail, completion_cue, caution, speech_text) values ('d3a7fed1-4290-5823-8261-cf4dd7d4f822'::uuid, '4035f341-c148-547a-8716-bf1b2b7188d1'::uuid, 4, 'finish', '옮길 것과 내보낼 것을 한 번에 처리해요.', '다른 방 물건은 바구니째 옮기고 쓰레기와 재활용은 정해진 배출 위치로 이동해요.', '분류 바구니가 작업 구역에 남아 있지 않아요.', '무거운 상자를 혼자 한 번에 들지 않아요.', '옮길 것과 내보낼 것을 한 번에 처리해요. 다른 방 물건은 바구니째 옮기고 쓰레기와 재활용은 정해진 배출 위치로 이동해요.');
insert into kb.step_source_links(procedure_version_id, step_no, source_version_id, section_locator, support_note) values ('4035f341-c148-547a-8716-bf1b2b7188d1'::uuid, 4, '789fb545-60ce-51e2-b513-d0a782645106'::uuid, 'verified-scope:aci_home_routine', '검수자가 단계 문안과 출처의 적용 범위를 대조함');
insert into kb.procedure_steps(id, procedure_version_id, step_no, stage_code, instruction, detail, completion_cue, caution, speech_text) values ('2a6d8adf-f6ed-517b-ab42-67834b89083d'::uuid, '4035f341-c148-547a-8716-bf1b2b7188d1'::uuid, 5, 'finish', '비워진 면과 통로를 확인해요.', '바닥과 문 앞에 걸리는 물건이 없는지 보고, 다음 구역은 새 미션으로 남겨요.', '선택한 한 구역과 통로가 정리됐어요.', null, '비워진 면과 통로를 확인해요. 바닥과 문 앞에 걸리는 물건이 없는지 보고, 다음 구역은 새 미션으로 남겨요.');
insert into kb.step_source_links(procedure_version_id, step_no, source_version_id, section_locator, support_note) values ('4035f341-c148-547a-8716-bf1b2b7188d1'::uuid, 5, '789fb545-60ce-51e2-b513-d0a782645106'::uuid, 'verified-scope:aci_home_routine', '검수자가 단계 문안과 출처의 적용 범위를 대조함');
insert into kb.review_events(id, entity_type, entity_version_id, decision, reason, reviewer_ref, created_at) values ('d3f0d3ff-9617-5bad-8daf-eacc98ab0750'::uuid, 'procedure_version', '4035f341-c148-547a-8716-bf1b2b7188d1'::uuid, 'approved', '단계 순서·출처 범위·안전 문구·실행 가능성 검수 완료', 'knowledge-editor-2026-08-25', '2026-08-25T06:00:00Z'::timestamptz);
insert into kb.procedures(id, procedure_key) values ('015565e8-0eab-5eeb-831b-78208a703331'::uuid, 'generic-laundry-v1');
insert into kb.procedure_versions(id, procedure_id, revision, status, locale, title, summary, required_step_count, content_hash) values ('6a9f3743-28c0-5ccc-8131-5173a3c2d069'::uuid, '015565e8-0eab-5eeb-831b-78208a703331'::uuid, 1, 'draft', 'ko-KR', '세탁할 천과 침구 정리', '세탁 라벨을 확인해 분리하고 권장 방법으로 세탁한 뒤 완전히 말려 제자리에 둬요.', 5, '0e2433cd29dc9fcb4ece122cfe553b9f86aebf924dc6d240776292a265ed61ae');
insert into kb.procedure_steps(id, procedure_version_id, step_no, stage_code, instruction, detail, completion_cue, caution, speech_text) values ('fc72c120-e519-59ff-a828-6eaf158879e7'::uuid, '6a9f3743-28c0-5ccc-8131-5173a3c2d069'::uuid, 1, 'prepare', '세탁할 천·의류·침구만 한곳에 모아요.', '주머니와 이물질을 확인하고 젖은 것과 마른 것을 섞어 오래 두지 않아요.', '세탁 대상만 바구니에 모였어요.', null, '세탁할 천·의류·침구만 한곳에 모아요. 주머니와 이물질을 확인하고 젖은 것과 마른 것을 섞어 오래 두지 않아요.');
insert into kb.step_source_links(procedure_version_id, step_no, source_version_id, section_locator, support_note) values ('6a9f3743-28c0-5ccc-8131-5173a3c2d069'::uuid, 1, 'fe74460b-c981-53e9-9c4b-0f06aa60b56a'::uuid, 'verified-scope:cdc_home_cleaning', '검수자가 단계 문안과 출처의 적용 범위를 대조함');
insert into kb.step_source_links(procedure_version_id, step_no, source_version_id, section_locator, support_note) values ('6a9f3743-28c0-5ccc-8131-5173a3c2d069'::uuid, 1, '789fb545-60ce-51e2-b513-d0a782645106'::uuid, 'verified-scope:aci_home_routine', '검수자가 단계 문안과 출처의 적용 범위를 대조함');
insert into kb.procedure_steps(id, procedure_version_id, step_no, stage_code, instruction, detail, completion_cue, caution, speech_text) values ('720bdab7-7d20-572a-bdb2-0ffaf38ab6bb'::uuid, '6a9f3743-28c0-5ccc-8131-5173a3c2d069'::uuid, 2, 'protect', '각 물건의 세탁 라벨을 확인해요.', '물세탁·손세탁·드라이클리닝과 건조 표시를 보고, 라벨이 없거나 불확실한 것은 따로 둬요.', '라벨을 확인한 것과 확인이 필요한 것이 분리됐어요.', '라벨을 모르면 임의로 세탁하지 않아요.', '각 물건의 세탁 라벨을 확인해요. 물세탁·손세탁·드라이클리닝과 건조 표시를 보고, 라벨이 없거나 불확실한 것은 따로 둬요.');
insert into kb.step_source_links(procedure_version_id, step_no, source_version_id, section_locator, support_note) values ('6a9f3743-28c0-5ccc-8131-5173a3c2d069'::uuid, 2, 'fe74460b-c981-53e9-9c4b-0f06aa60b56a'::uuid, 'verified-scope:cdc_home_cleaning', '검수자가 단계 문안과 출처의 적용 범위를 대조함');
insert into kb.step_source_links(procedure_version_id, step_no, source_version_id, section_locator, support_note) values ('6a9f3743-28c0-5ccc-8131-5173a3c2d069'::uuid, 2, '789fb545-60ce-51e2-b513-d0a782645106'::uuid, 'verified-scope:aci_home_routine', '검수자가 단계 문안과 출처의 적용 범위를 대조함');
insert into kb.procedure_steps(id, procedure_version_id, step_no, stage_code, instruction, detail, completion_cue, caution, speech_text) values ('7ab97ccc-62b7-5e7c-bff5-cab6191399da'::uuid, '6a9f3743-28c0-5ccc-8131-5173a3c2d069'::uuid, 3, 'act', '색상과 라벨 방법이 비슷한 것끼리 나눠요.', '색이 빠질 수 있는 것, 섬세한 것, 수건·행주처럼 용도가 다른 것을 구분해요.', '함께 세탁할 묶음이 정해졌어요.', null, '색상과 라벨 방법이 비슷한 것끼리 나눠요. 색이 빠질 수 있는 것, 섬세한 것, 수건·행주처럼 용도가 다른 것을 구분해요.');
insert into kb.step_source_links(procedure_version_id, step_no, source_version_id, section_locator, support_note) values ('6a9f3743-28c0-5ccc-8131-5173a3c2d069'::uuid, 3, '789fb545-60ce-51e2-b513-d0a782645106'::uuid, 'verified-scope:aci_home_routine', '검수자가 단계 문안과 출처의 적용 범위를 대조함');
insert into kb.procedure_steps(id, procedure_version_id, step_no, stage_code, instruction, detail, completion_cue, caution, speech_text) values ('3fa9d96d-b329-5b2a-92ea-90e5fc127831'::uuid, '6a9f3743-28c0-5ccc-8131-5173a3c2d069'::uuid, 4, 'act', '라벨의 세탁 방법과 권장 물 온도를 따라요.', '세탁기나 손세탁 방법을 라벨대로 선택하고 한 번에 너무 많이 넣지 않아요.', '라벨에 맞는 방법으로 세탁이 끝났어요.', null, '라벨의 세탁 방법과 권장 물 온도를 따라요. 세탁기나 손세탁 방법을 라벨대로 선택하고 한 번에 너무 많이 넣지 않아요.');
insert into kb.step_source_links(procedure_version_id, step_no, source_version_id, section_locator, support_note) values ('6a9f3743-28c0-5ccc-8131-5173a3c2d069'::uuid, 4, 'fe74460b-c981-53e9-9c4b-0f06aa60b56a'::uuid, 'verified-scope:cdc_home_cleaning', '검수자가 단계 문안과 출처의 적용 범위를 대조함');
insert into kb.procedure_steps(id, procedure_version_id, step_no, stage_code, instruction, detail, completion_cue, caution, speech_text) values ('d2b2c93d-d636-583a-b481-2db57a254fa8'::uuid, '6a9f3743-28c0-5ccc-8131-5173a3c2d069'::uuid, 5, 'dry', '완전히 말린 뒤 제자리에 둬요.', '라벨의 건조 방법을 따르고 습기가 남지 않은 것을 확인한 뒤 수납해요. 세탁 바구니도 비워 닦아요.', '세탁물이 완전히 마르고 바구니가 비었어요.', null, '완전히 말린 뒤 제자리에 둬요. 라벨의 건조 방법을 따르고 습기가 남지 않은 것을 확인한 뒤 수납해요. 세탁 바구니도 비워 닦아요.');
